function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) {
  return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] };
}

function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews) {
  return { id, skillId, stem, options, answerIndex, reasons, difficulty, cognitiveProcess: ["消化系統判讀", "證據推理"], representationType: "文字與資料判讀", misconceptionTargets: [], reviews, assets: [] };
}

function stimulus(id, skillId, type, content, accessibility, questions) {
  return { id, skillId, type, content, accessibility, questions, assets: [] };
}

const lectures = [];
const questions = [];
const stimuli = [];

lectures.push(lecture("BIO_R4_L_S049", "BIO_R4_S049",
  ["依食物通過方向辨識人體消化道主要器官。", "區分消化道與附屬消化器官，能由相鄰位置判斷路徑。"],
  [
    { id: "BIO_R4_L_S049_SEC_01", title: "消化道是一條連續管道", content: "食物由口腔進入後，依序經咽、食道、胃、小腸、大腸，最後由肛門排出未被消化吸收的殘餘。順序代表食物實際通過的路徑，不等於每處消化作用強度相同。" },
    { id: "BIO_R4_L_S049_SEC_02", title: "口腔到胃的前段", content: "口腔負責攝入、咀嚼並與唾液混合；吞嚥後食團通過咽與食道到胃。食道主要靠肌肉運動推送食物，不是食物由重力自由落下的空管。" },
    { id: "BIO_R4_L_S049_SEC_03", title: "小腸與大腸的後段", content: "胃之後是小腸，小腸是多種養分消化完成與吸收的重要場所；其後才進入大腸，主要吸收部分水分並形成糞便。不能因名稱有大字就誤認大腸位於小腸之前。" },
    { id: "BIO_R4_L_S049_SEC_04", title: "附屬器官不在通道內", content: "肝臟、膽囊與胰臟會製造、儲存或分泌消化相關液體，但食物本身不會依序穿過這些器官。題目問食物路徑時，應選連續消化道；問消化液來源時才考慮附屬器官。" },
  ],
  [
    { id: "BIO_R4_L_S049_EX_01", prompt: "食物離開胃後會先進入小腸還是大腸？", steps: ["回想消化道由前向後的連續順序。", "定位胃後方相鄰器官為小腸。"], answer: "小腸", why: "正常消化道順序是胃接小腸，再接大腸；名稱大小不代表通過先後，因此不能因大腸字樣而提前。" },
    { id: "BIO_R4_L_S049_EX_02", prompt: "膽汁進入小腸，能否說食物會穿過肝臟？", steps: ["區分消化液來源與食物路徑。", "確認肝臟不是消化道管腔的一段。"], answer: "不能", why: "肝臟製造的膽汁可經管道進入小腸，但食物仍沿胃、小腸的管腔移動，不會因膽汁來源而穿過肝臟。" },
    { id: "BIO_R4_L_S049_EX_03", prompt: "某物質依序經口腔、食道、胃，下一站最可能是哪裡？", steps: ["辨識題幹已走完消化道前段。", "接續胃後的主要消化道器官。"], answer: "小腸", why: "口腔、食道、胃是連續前段，胃出口接小腸；咽在食道之前，大腸則位於小腸之後，因此下一站是小腸。" },
  ],
  [
    { belief: "食物會穿過肝臟和胰臟。", whyWrong: "這些器官提供消化液，但不是食物通過的消化道管腔。", correction: "路徑題只排列口腔、咽、食道、胃、小腸、大腸與肛門。" },
    { belief: "大腸名稱較大，所以位於小腸之前。", whyWrong: "大小名稱描述構造特徵，不決定食物通過的時間順序。", correction: "以管道相接位置判斷，食物先經小腸再進大腸。" },
    { belief: "食道只是靠重力讓食物落到胃。", whyWrong: "食道壁肌肉可產生推進運動，即使姿勢改變仍能運送食團。", correction: "把食道視為會主動推送食物的肌肉性管道，而非被動直管。" },
    { belief: "每個消化道器官都執行完全相同功能。", whyWrong: "各段在攝入、運送、消化、吸收與排出方面有不同主要角色。", correction: "先辨識路徑順序，再依各器官主要功能回答進一步問題。" },
  ],
  [
    { prompt: "胃之後食物先進入哪個器官？", answer: "小腸", reason: "小腸直接連接胃的出口，是食物離開胃後的下一段消化道。" },
    { prompt: "食物正常會不會穿過胰臟？", answer: "不會", reason: "胰臟分泌消化液進入小腸，但本身不是食物通過的管道。" },
    { prompt: "小腸與大腸何者在食物路徑較前？", answer: "小腸", reason: "消化道後段順序是胃、小腸、大腸，再由末端排出殘餘。" },
  ],
));

questions.push(
  question("BIO_R4_Q_049_01", "BIO_R4_S049", "foundation", "食物由口腔吞下後，正常會先經過哪一個構造？", ["咽部", "胃部", "小腸", "大腸"], 0, ["咽位於口腔後方，是吞嚥後先通過的構造。", "胃位於食道之後，不會直接接在口腔後。", "小腸在胃之後，路徑位置更後方。", "大腸還位於小腸之後，不是第一站。"], ["依消化道前段順序，口腔後先經咽，再進食道與胃。", "「胃部」、「小腸」、「大腸」都位於路徑較後段，不能跨越中間相連器官。"]),
  question("BIO_R4_Q_049_02", "BIO_R4_S049", "foundation", "食團通過食道之後，會進入下列哪一個器官？", ["小腸", "胃部", "大腸", "肛門"], 1, ["小腸與食道之間還隔著胃。", "胃直接承接由食道送下的食團。", "大腸位於小腸之後，並不接食道。", "肛門是消化道末端，距離食道很遠。"], ["食道的下端連接胃，所以食團下一站是胃。", "由器官相鄰關係即可排除位於胃後方或消化道末端的選項。"]),
  question("BIO_R4_Q_049_03", "BIO_R4_S049", "foundation", "食物離開胃後，正常消化道的下一段是什麼？", ["口腔", "食道", "小腸", "肝臟"], 2, ["口腔是消化道起點，不在胃後。", "食道在胃之前，不能成為下一段。", "小腸直接接在胃之後，順序正確。", "肝臟不是食物直接通過的消化道。"], ["胃的出口連接小腸，食物會先進入小腸再到大腸。", "肝臟雖與消化相關，但其分泌物進入小腸，食物不穿過肝臟。"]),
  question("BIO_R4_Q_049_04", "BIO_R4_S049", "standard", "下列哪一組最符合食物通過人體消化道的方向？", ["胃→食道→口腔", "大腸→小腸→胃", "小腸→胃→食道", "口腔→食道→胃"], 3, ["這個順序把前段路徑完全倒轉。", "正常是胃到小腸再到大腸。", "小腸位於胃後，不能先進小腸再回胃。", "此順序符合消化道由入口向後的方向。"], ["口腔攝入後經食道到胃，是四項中唯一方向正確的連續片段。", "「胃→食道→口腔」、「大腸→小腸→胃」、「小腸→胃→食道」都將正常的前後位置反向排列，沒有第二個可行路徑。"]),
  question("BIO_R4_Q_049_05", "BIO_R4_S049", "standard", "下列哪個器官不屬於食物直接通過的消化道？", ["肝臟", "胃部", "小腸", "大腸"], 0, ["肝臟製造膽汁，但食物不直接穿過肝臟。", "胃是食物通過並進行消化的管道器官。", "小腸是胃後方的重要消化吸收管道。", "大腸也是消化道後段的一部分。"], ["題目問食物直接通過，肝臟屬附屬消化器官而非管道。", "胃、小腸與大腸彼此連續，皆有食物或殘餘物通過。"]),
  question("BIO_R4_Q_049_06", "BIO_R4_S049", "standard", "食物依序通過胃、小腸後，下一個主要器官是哪一個？", ["咽部", "大腸", "口腔", "胰臟"], 1, ["咽位於食道之前，已在路徑前段通過。", "大腸承接小腸後未被吸收的內容物。", "口腔是食物進入人體的起點。", "胰臟提供消化液但食物不穿過其中。"], ["胃後接小腸，小腸後接大腸，因此答案為大腸。", "其他選項不是已通過的前段器官，就是不屬食物管道的附屬器官。"]),
  question("BIO_R4_Q_049_07", "BIO_R4_S049", "standard", "膽汁由肝臟產生並進入小腸，這項事實可說明什麼？", ["食物先穿過肝臟", "肝臟位於大腸末端", "附屬器官的分泌物可進入消化道", "肝臟就是小腸的一部分"], 2, ["膽汁來源不代表食物會穿過肝臟。", "肝臟不是大腸末端的管道構造。", "分泌物進入小腸正符合附屬器官角色。", "肝臟與小腸是兩個不同器官。"], ["肝臟不在食物路徑內，但其分泌物能經管道進入小腸。", "「附屬器官的分泌物可進入消化道」正確區分器官位置與分泌功能，其他項目混淆食物和膽汁路徑。"]),
  question("BIO_R4_Q_049_08", "BIO_R4_S049", "advanced", "若食團已到達胃，接下來不可能直接進入哪個構造？", ["胃出口", "小腸前段", "與小腸相連處", "口腔"], 3, ["食團會由胃出口離開胃。", "小腸前段直接承接胃內容物。", "胃與小腸相連處正位於接續路徑。", "正常路徑不會由胃直接返回口腔。"], ["正常單向路徑由胃向小腸前進，不會跳回入口口腔。", "「胃出口」、「小腸前段」、「與小腸相連處」描述胃離開並接入小腸的相鄰位置，皆可能位於下一段。"]),
  question("BIO_R4_Q_049_09", "BIO_R4_S049", "advanced", "某物依序出現在食道、胃、小腸，可推論此物最可能是什麼？", ["沿消化道移動的食物內容物", "只在血管內流動的血液", "由肺泡交換的空氣", "只在神經傳遞的訊息"], 0, ["三處連續構成食物通過的消化道路徑。", "血液不會依序流經食道管腔與胃腔。", "空氣主要通過呼吸道而不是小腸。", "神經訊息沿神經細胞傳遞，不在消化道腔移動。"], ["食道、胃與小腸的連續出現正符合食物內容物移動。", "其他三者各有不同的運輸系統，不能以此器官順序解釋。"]),
  question("BIO_R4_Q_049_10", "BIO_R4_S049", "advanced", "某示意圖把胰臟畫在小腸旁，判斷食物路徑時應如何處理？", ["將食物安排穿過胰臟", "辨識胰液進入小腸，但食物沿小腸通過", "把胰臟當成大腸末端", "刪除小腸並改走胰臟"], 1, ["胰臟不是食物通過的管腔。", "此項正確區分分泌物流向與食物路徑。", "胰臟與大腸末端沒有這種連續關係。", "小腸是正常消化道不可任意刪除。"], ["器官畫得相鄰不等於食物穿過，需看管道連接與分泌方向。", "胰液可進入小腸協助消化，食物本身仍在小腸腔內前進。"]),
  question("BIO_R4_Q_049_11", "BIO_R4_S049", "transfer", "吞下藥錠後要到小腸溶解，藥錠到達小腸前必經哪組器官？", ["肝臟與胰臟", "肺與氣管", "食道與胃", "腎臟與膀胱"], 2, ["藥錠不會沿肝胰實質組織通過。", "肺與氣管屬呼吸道而非消化道。", "吞嚥後先經食道、胃才到小腸。", "腎臟膀胱屬泌尿系統，不是入口路徑。"], ["口服物沿消化道前進，到小腸前必先通過食道與胃。", "其餘配對分屬附屬消化、呼吸或泌尿器官，並非連續管道。"]),
  question("BIO_R4_Q_049_12", "BIO_R4_S049", "transfer", "內視鏡從口腔進入並依正常消化道向後，哪個順序最合理？", ["小腸→食道→胃", "胃→咽→口腔", "大腸→胃→食道", "咽→食道→胃"], 3, ["小腸不會位於食道與胃之前。", "此順序朝入口反向移動。", "大腸與胃間還隔著小腸且方向相反。", "此為口腔後方的連續前段順序。"], ["從口腔向後，內視鏡會先經咽，再經食道到胃。", "「咽→食道→胃」是唯一連續且方向正確的片段，其他選項皆倒序或跳段。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S049", "BIO_R4_S049", "route-log",
  { title: "膠囊定位紀錄", text: "研究者使用不被消化的微型定位膠囊，依時間記錄它所在的消化道位置。膠囊只沿消化道管腔移動，不進入肝臟、胰臟或血管。表中的時間為到達各位置的先後紀錄。", note: "紀錄只用來判斷路徑，不代表膠囊在每個器官停留時間相同。" },
  { summary: "表格以時間順序列出膠囊所在的四個消化道位置。", colorIndependent: true, dataFallback: { columns: ["時間", "位置"], rows: [["08:00", "口腔"], ["08:01", "食道"], ["08:05", "胃"], ["10:20", "小腸"]] } },
  [
    question("BIO_R4_SQ_049_01", "BIO_R4_S049", "standard", "依定位紀錄，膠囊離開食道後先到達哪個器官？", ["胃部", "口腔", "小腸", "肝臟"], 0, ["08:01食道之後的08:05位置是胃。", "口腔出現在食道之前，並非下一站。", "小腸在胃之後才被記錄到。", "材料明示膠囊不進入肝臟。"], ["定位表由八時一分的食道接到八時五分的胃部，胃是離開食道後的第一站。", "此結果也符合食道下端連接胃的正常消化道路徑。"]),
    question("BIO_R4_SQ_049_02", "BIO_R4_S049", "advanced", "這份資料為何不能證明膠囊曾穿過胰臟？", ["胰臟比胃小", "胰臟不是消化道管腔的一段", "小腸沒有消化作用", "膠囊會變成血液"], 1, ["器官大小不是判斷路徑的依據。", "胰臟分泌胰液，但食物不直接通過其中。", "小腸是重要消化與吸收場所。", "定位膠囊不會轉變成血液成分。"], ["材料限定膠囊沿消化道腔移動，而胰臟屬附屬器官。", "因此即使胰液流向小腸，也不能把分泌物流向當成膠囊路徑。"]),
    question("BIO_R4_SQ_049_03", "BIO_R4_S049", "transfer", "若繼續追蹤膠囊，離開小腸後最可能先記錄到哪裡？", ["食道", "胃部", "大腸", "口腔"], 2, ["食道位於胃之前，已經通過。", "胃在小腸前方，並非後續位置。", "大腸直接承接小腸後的內容物。", "口腔是整段消化道的入口。"], ["利用已知消化道順序，小腸之後的下一主要段落是大腸。", "此為由現有路徑向後預測，不需要假設膠囊進入附屬器官。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S050", "BIO_R4_S050",
  ["區分物理性消化與化學性消化的判準。", "由顆粒大小、分子種類與酵素作用證據判斷消化類型。"],
  [
    { id: "BIO_R4_L_S050_SEC_01", title: "物理性消化改變外形", content: "咀嚼、切碎與胃的攪拌可使食物顆粒變小並與消化液混合，增加接觸面積，但食物中大分子的種類尚未因此改變。判準是外形、大小或混合狀態改變。" },
    { id: "BIO_R4_L_S050_SEC_02", title: "化學性消化改變分子", content: "消化酵素能把澱粉、蛋白質等較大分子分解成較小分子，使物質種類或分子結構改變。化學性消化不是把食物磨細，而是發生特定化學反應。" },
    { id: "BIO_R4_L_S050_SEC_03", title: "兩類作用可連續發生", content: "口腔中牙齒咀嚼屬物理性消化，唾液酵素分解澱粉則屬化學性消化；胃的攪拌與酵素作用也可同時存在。不能把一個器官固定只配一種消化。" },
    { id: "BIO_R4_L_S050_SEC_04", title: "接觸面積連結速率", content: "切成小塊不會直接把大分子變成可吸收小分子，卻能增加總表面積，讓酵素有更多接觸位置，間接加快後續化學性消化。解題時需分清直接改變與促進作用。" },
  ],
  [
    { id: "BIO_R4_L_S050_EX_01", prompt: "牙齒把饅頭咬碎，屬於哪類消化？", steps: ["觀察改變的是顆粒大小。", "確認沒有證據顯示分子種類改變。"], answer: "物理性消化", why: "咀嚼只使饅頭碎成較小顆粒，增加表面積，未直接證明澱粉分子已變成其他小分子，因此屬物理性消化。" },
    { id: "BIO_R4_L_S050_EX_02", prompt: "唾液酵素使澱粉形成較小分子，屬於哪類消化？", steps: ["找出酵素參與反應的線索。", "確認澱粉分子被轉變為不同分子。"], answer: "化學性消化", why: "受質澱粉的分子結構發生改變並形成較小分子，符合化學反應與化學性消化的判準。" },
    { id: "BIO_R4_L_S050_EX_03", prompt: "將食物切碎後酵素分解較快，切碎本身是否為化學性消化？", steps: ["區分切碎的直接結果與後續酵素作用。", "判斷切碎是否改變分子種類。"], answer: "不是，切碎本身是物理性消化", why: "切碎增加接觸面積，因而促進後續酵素反應；但切碎本身只改變顆粒大小，沒有改變食物分子的種類。" },
  ],
  [
    { belief: "食物變小就一定是化學性消化。", whyWrong: "顆粒變小可能只是切碎或咀嚼，分子種類尚未改變。", correction: "先問改變的是外形大小或分子結構，再決定消化類型。" },
    { belief: "只要在口腔發生就都是物理性消化。", whyWrong: "口腔除咀嚼外，唾液酵素也能進行化學性消化。", correction: "依實際作用判斷，同一器官可同時具有物理與化學性消化。" },
    { belief: "胃的攪拌會直接把蛋白質分子切斷。", whyWrong: "攪拌改變混合與顆粒狀態，分子分解需由相應化學反應完成。", correction: "把胃的攪拌歸為物理作用，酵素分解蛋白質才是化學作用。" },
    { belief: "物理性消化對化學性消化完全沒有幫助。", whyWrong: "顆粒變小可增加酵素接觸面積，使後續化學反應更有效率。", correction: "兩類消化判準不同，卻能前後配合完成食物分解。" },
  ],
  [
    { prompt: "牙齒把食物磨碎屬於哪類消化？", answer: "物理性消化", reason: "磨碎只改變顆粒大小與表面積，沒有直接改變分子種類。" },
    { prompt: "酵素把蛋白質分解屬於哪類消化？", answer: "化學性消化", reason: "蛋白質分子經反應形成較小分子，物質結構已經改變。" },
    { prompt: "同一器官能否同時發生兩類消化？", answer: "可以", reason: "例如口腔同時有牙齒咀嚼與唾液酵素分解澱粉。" },
  ],
));

questions.push(
  question("BIO_R4_Q_050_01", "BIO_R4_S050", "foundation", "牙齒將食物咬成較小顆粒，主要屬於哪一類消化？", ["物理性消化", "化學性消化", "氣體交換", "血液循環"], 0, ["咀嚼改變顆粒大小，屬於物理作用。", "題幹沒有分子種類改變的證據。", "咀嚼不涉及氧與二氧化碳交換。", "食物磨碎不是血液流動的過程。"], ["判準是食物外形與大小改變，沒有新的分子形成，因此是物理性消化。", "「化學性消化」、「氣體交換」、「血液循環」或需要化學轉變證據，或分屬呼吸與循環功能。"]),
  question("BIO_R4_Q_050_02", "BIO_R4_S050", "foundation", "消化酵素將大分子分解成小分子，屬於哪類作用？", ["物理性消化", "化學性消化", "排遺", "吞嚥"], 1, ["物理作用不改變分子種類。", "酵素使分子結構改變，符合化學作用。", "排遺是排出未消化殘餘。", "吞嚥是將食團送入咽與食道。"], ["題幹明示大分子形成小分子，分子結構發生改變。", "因此答案為化學性消化，而非運送、排出或只改變外形的作用。"]),
  question("BIO_R4_Q_050_03", "BIO_R4_S050", "foundation", "下列哪一個現象最能代表物理性消化？", ["澱粉變成小分子", "蛋白質被酵素分解", "胃攪拌使食物混合", "養分進入微血管"], 2, ["澱粉分子改變屬化學性消化。", "酵素分解蛋白質也是化學反應。", "攪拌只改變混合與顆粒狀態。", "進入微血管是吸收而非消化。"], ["胃的攪拌沒有直接改變分子種類，符合物理性消化判準。", "「澱粉變成小分子」、「蛋白質被酵素分解」、「養分進入微血管」分別涉及化學分解或吸收，作用類型不同。"]),
  question("BIO_R4_Q_050_04", "BIO_R4_S050", "standard", "判斷化學性消化最關鍵的證據是什麼？", ["食物位置改變", "食物顏色較深", "顆粒數量增加", "大分子轉變成不同的小分子"], 3, ["位置改變只表示運送。", "顏色變深不必然代表消化反應。", "切碎會增加顆粒數但仍屬物理作用。", "分子種類或結構改變是化學反應證據。"], ["化學性消化的核心是物質分子發生轉變，不只是外觀改變。", "「大分子轉變成不同的小分子」直接描述大分子形成小分子，符合唯一判準。"]),
  question("BIO_R4_Q_050_05", "BIO_R4_S050", "standard", "把肉切成細末後再加入蛋白酶，切碎的直接作用為何？", ["增加酵素可接觸的表面積", "直接將蛋白質變成胺基酸", "使蛋白酶成為能量", "讓所有養分立即被吸收"], 0, ["小顆粒總表面積較大，利於酵素接觸。", "切刀只能改變外形，不能完成分子分解。", "切碎不會改變蛋白酶的物質角色。", "吸收仍需消化與腸道運輸過程。"], ["切碎屬物理性消化，主要價值是增加後續酵素作用的接觸面。", "它不會直接完成化學分解、改變酵素角色或跳過吸收程序。"]),
  question("BIO_R4_Q_050_06", "BIO_R4_S050", "standard", "口腔中同時可能發生哪一組作用？", ["只有排遺與排泄", "牙齒咀嚼與唾液酵素作用", "肺泡交換與血液循環", "尿液形成與汗液蒸發"], 1, ["口腔不是排遺與排泄器官。", "兩者分別代表物理與化學性消化。", "氣體交換主要在肺泡而非口腔。", "尿液與汗液形成不在口腔。"], ["口腔既有牙齒改變食物顆粒，也有唾液酵素分解澱粉。", "「牙齒咀嚼與唾液酵素作用」正確呈現同一器官可同時發生兩類消化。"]),
  question("BIO_R4_Q_050_07", "BIO_R4_S050", "standard", "胃壁肌肉攪拌食物，但未改變分子種類，應歸類為何？", ["化學性消化", "吸收", "物理性消化", "細胞呼吸"], 2, ["沒有分子改變證據，不能歸為化學反應。", "攪拌不是養分穿過腸壁的吸收。", "混合與顆粒狀態改變符合物理作用。", "細胞呼吸發生在細胞內釋放能量。"], ["題幹特別指出分子種類未改變，因此胃的攪拌是物理性消化。", "不能因作用發生在胃就一律判為化學性消化。"]),
  question("BIO_R4_Q_050_08", "BIO_R4_S050", "advanced", "同樣食物切碎組比整塊組分解快，最合理的解釋是什麼？", ["切碎組的分子種類先改變", "整塊組完全沒有受質", "切碎直接增加酵素總量", "切碎增加接觸面積，促進後續化學消化"], 3, ["切碎本身只改變顆粒，不先改變分子。", "整塊食物仍含可被作用的受質。", "切碎沒有額外加入任何酵素。", "較大總表面積提高酵素接觸機會。"], ["物理性切碎可增加接觸面，間接使酵素分解更快。", "「切碎增加接觸面積，促進後續化學消化」能同時解釋切碎的物理本質與後續速率差異。"]),
  question("BIO_R4_Q_050_09", "BIO_R4_S050", "advanced", "某作用只讓食物從塊狀變糊狀，檢測分子種類不變，應如何判斷？", ["主要是物理性消化", "必定是完整化學性消化", "已完成全部吸收", "已轉變成血液"], 0, ["外形改變而分子不變符合物理性消化。", "化學性消化需有分子結構改變。", "糊狀不代表已穿過腸壁吸收。", "食物不會因變糊就直接成為血液。"], ["兩項證據分別是形態改變與分子不變，結論明確指向物理作用。", "不能只看食物變得不一樣就忽略分子檢測結果。"]),
  question("BIO_R4_Q_050_10", "BIO_R4_S050", "advanced", "若酵素作用前後顆粒外形相同，但檢出新的小分子，這表示什麼？", ["沒有任何消化作用", "發生化學性消化", "只有物理性切碎", "只發生食物運送"], 1, ["新小分子形成表示已有物質轉變。", "分子種類改變是化學性消化證據。", "外形相同且未切碎，不支持只有物理作用。", "運送不會產生新的小分子。"], ["肉眼外形不變不能排除化學反應，新小分子才是關鍵證據。", "「發生化學性消化」依分子層次判斷，避免把消化限制為可見的顆粒變化。"]),
  question("BIO_R4_Q_050_11", "BIO_R4_S050", "transfer", "嬰兒副食品先磨成泥，這項處理如何幫助消化？", ["直接製造所有消化酵素", "讓食物立刻進入血液", "增大接觸面並方便後續酵素作用", "把所有大分子立刻分解完成"], 2, ["研磨不會製造消化酵素。", "食物仍需經消化與吸收過程。", "顆粒變小可增加與酵素接觸面。", "研磨只改外形，未完成全部化學分解。"], ["磨泥是物理性處理，能增加表面積並方便後續化學消化。", "「增大接觸面並方便後續酵素作用」保留直接與間接作用差異，沒有把研磨誇大為完成吸收。"]),
  question("BIO_R4_Q_050_12", "BIO_R4_S050", "transfer", "要證明某處理造成化學性消化，哪種資料最有力？", ["顆粒變得更小", "食物移動距離增加", "容器外觀改變", "處理後出現原先沒有的較小分子"], 3, ["顆粒變小只能證明物理性改變。", "移動距離只反映位置變化。", "容器外觀與食物分子無關。", "新小分子出現直接支持物質轉變。"], ["化學性消化需要分子種類或結構改變的證據。", "「處理後出現原先沒有的較小分子」直接比較處理前後分子，證據力高於外形、位置或容器變化。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S050", "BIO_R4_S050", "digestion-test",
  { title: "餅乾處理比較", text: "甲組把餅乾磨碎後只加水，乙組把等量餅乾磨碎後加入含澱粉酵素的溶液。兩組溫度、時間與液體體積相同。十分鐘後檢測顆粒大小及是否出現由澱粉分解形成的小分子。", note: "磨碎在加入液體前完成，因此兩組起始顆粒大小相近。" },
  { summary: "表格比較磨碎加水組與磨碎加酵素組的外形及分子檢測結果。", colorIndependent: true, dataFallback: { columns: ["組別", "處理", "顆粒狀態", "小分子檢測"], rows: [["甲", "磨碎後加水", "細小", "未檢出"], ["乙", "磨碎後加酵素液", "細小", "檢出"]] } },
  [
    question("BIO_R4_SQ_050_01", "BIO_R4_S050", "standard", "兩組餅乾在加入液體前都磨碎，磨碎本身屬於什麼？", ["排遺", "化學性消化", "吸收", "物理性消化"], 3, ["排遺是排出未消化的食物殘餘。", "化學性消化需有新的分子形成。", "吸收是養分穿過腸壁進入循環。", "磨碎只使顆粒變小，沒有分子改變證據。"], ["磨碎的直接結果是顆粒變細，符合物理性消化判準。", "後續是否出現小分子要另由酵素處理與檢測結果判斷。"]),
    question("BIO_R4_SQ_050_02", "BIO_R4_S050", "advanced", "乙組檢出小分子而甲組未檢出，最能支持哪項結論？", ["酵素液使澱粉發生化學性消化", "水能分解所有澱粉", "磨碎使乙組酵素量變零", "甲組已完成全部吸收"], 0, ["唯一主要差異為酵素液，且形成新小分子。", "甲組有水卻未檢出小分子。", "題幹沒有顯示酵素量變零。", "此為容器實驗，沒有腸壁可供吸收。"], ["乙組相較甲組多了酵素，並出現澱粉分解的小分子。", "結果支持化學性消化，不能把作用歸給水、磨碎或不存在的吸收。"]),
    question("BIO_R4_SQ_050_03", "BIO_R4_S050", "transfer", "若想單獨比較磨碎是否加快酵素作用，應新增哪種組別？", ["不同食物且不同溫度", "等量整塊餅乾加相同酵素液", "只放空容器不加餅乾", "磨碎餅乾但改用不同pH"], 1, ["食物與溫度同時不同會造成混淆。", "只改顆粒大小可與乙組公平比較。", "空容器無法比較顆粒大小效果。", "pH不同會加入另一個影響酵素的變因。"], ["研究磨碎效果需固定酵素、食物量與環境，只改顆粒大小。", "新增整塊加相同酵素液組，才能檢驗接觸面積對速率的影響。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S051", "BIO_R4_S051",
  ["連結消化液、消化酵素與醣類、蛋白質、脂質的分解。", "區分膽汁的乳化作用與酵素的化學分解作用。"],
  [
    { id: "BIO_R4_L_S051_SEC_01", title: "消化液與酵素不完全相同", content: "消化液是由消化器官分泌或輸送到消化道的液體，其中可能含消化酵素，也可能含不屬酵素的成分。作答時不能把每一種消化液都直接等同一種酵素。" },
    { id: "BIO_R4_L_S051_SEC_02", title: "醣類與蛋白質消化", content: "唾液中的澱粉酵素可開始分解澱粉；胃與小腸中的相關酵素則參與蛋白質分解。不同酵素具有專一性，分解澱粉的酵素不能任意改成分解蛋白質。" },
    { id: "BIO_R4_L_S051_SEC_03", title: "脂質分解與膽汁乳化", content: "脂質在小腸可由脂質酵素進行化學分解。膽汁可把大油滴分散成許多小油滴，增加脂質酵素接觸面積；膽汁本身不含消化酵素，也不直接把脂質分子分解完成。" },
    { id: "BIO_R4_L_S051_SEC_04", title: "由產物辨識作用", content: "若資料顯示澱粉減少並出現小分子，可判斷有適合的酵素作用；若只看到油滴由大變小而脂質分子未改變，則是乳化。要同時看受質、產物與作用位置，不能只憑液體名稱猜答案。" },
  ],
  [
    { id: "BIO_R4_L_S051_EX_01", prompt: "唾液與澱粉混合後出現較小分子，主要是哪種作用？", steps: ["辨認受質是澱粉。", "連結唾液中的澱粉酵素與化學分解。"], answer: "唾液澱粉酵素分解澱粉", why: "題幹同時提供唾液、澱粉與新小分子三項證據，符合澱粉酵素催化化學性消化，而非只有食物混合。" },
    { id: "BIO_R4_L_S051_EX_02", prompt: "膽汁使大油滴變成小油滴，是否已把脂質分子完全分解？", steps: ["區分油滴大小與脂質分子結構。", "判斷膽汁的直接作用是乳化。"], answer: "沒有，只是乳化分散", why: "油滴變小增加總接觸面，但脂質分子仍需脂質酵素進行化學分解，因此不能把乳化等同消化完成。" },
    { id: "BIO_R4_L_S051_EX_03", prompt: "蛋白質酵素加入澱粉後沒有產物，最合理的解釋為何？", steps: ["確認酵素與受質種類不同。", "運用酵素專一性判斷配對。"], answer: "該酵素不適合澱粉受質", why: "分解蛋白質的酵素作用部位適合特定蛋白質受質，不能因都是養分就任意分解澱粉，結果符合專一性。" },
  ],
  [
    { belief: "所有消化液都一定含酵素。", whyWrong: "膽汁能協助脂質消化，卻不含負責化學分解的消化酵素。", correction: "逐一辨識消化液成分與作用，不用液字直接推成含酵素。" },
    { belief: "膽汁會直接把脂質分子分解成小分子。", whyWrong: "膽汁只把油滴分散，脂質分子的化學分解仍需脂質酵素。", correction: "把膽汁乳化列為增加接觸面，把脂質酵素列為化學分解。" },
    { belief: "一種消化酵素可以分解全部養分。", whyWrong: "酵素具有專一性，澱粉、蛋白質與脂質需要相應酵素作用。", correction: "由受質種類選擇酵素，不因都屬食物成分就視為通用。" },
    { belief: "消化液一加入，養分就立刻全部吸收。", whyWrong: "消化是分解過程，吸收還需小分子穿過小腸壁進入循環。", correction: "依序區分消化液作用、形成小分子與小腸吸收三個步驟。" },
  ],
  [
    { prompt: "唾液中的澱粉酵素主要作用哪種養分？", answer: "澱粉", reason: "酵素具有專一性，唾液澱粉酵素可開始分解澱粉分子。" },
    { prompt: "膽汁直接作用會改變什麼？", answer: "油滴大小", reason: "膽汁乳化使大油滴分散為小油滴，增加脂質酵素接觸面。" },
    { prompt: "脂質分子的化學分解需要什麼？", answer: "脂質酵素", reason: "乳化只改變油滴分散狀態，分子分解仍需相應酵素催化。" },
  ],
));

questions.push(
  question("BIO_R4_Q_051_01", "BIO_R4_S051", "foundation", "唾液中的澱粉酵素最直接作用於哪種物質？", ["澱粉", "蛋白質", "脂質", "礦物質"], 0, ["澱粉是此酵素適合的受質。", "蛋白質需由相應蛋白質酵素分解。", "脂質需脂質酵素且可受膽汁乳化協助。", "礦物質不需經酵素分解成小分子。"], ["酵素名稱與專一性共同指出受質為澱粉。", "其餘養分類別的化學性質不同，不能由唾液澱粉酵素任意分解。"]),
  question("BIO_R4_Q_051_02", "BIO_R4_S051", "foundation", "膽汁對脂質消化的主要協助是什麼？", ["把脂質直接變成胺基酸", "將大油滴乳化成小油滴", "製造新的脂質分子", "把脂質送進肺泡"], 1, ["胺基酸是蛋白質分解相關小分子。", "乳化可增加脂質酵素接觸面積。", "膽汁不會製造更多脂質分子。", "肺泡進行氣體交換，不是脂質消化場所。"], ["膽汁的直接作用是分散油滴，不是催化脂質分子的化學分解。", "「將大油滴乳化成小油滴」正確描述乳化，其他項目混淆產物、合成或器官系統。"]),
  question("BIO_R4_Q_051_03", "BIO_R4_S051", "foundation", "脂質分子要進行化學性消化，主要需要哪一種物質？", ["膽汁色素", "水分", "脂質酵素", "紅血球"], 2, ["膽汁色素不是分解脂質的催化劑。", "水是反應環境但不具脂質酵素專一性。", "脂質酵素可催化脂質分子分解。", "紅血球負責運氧，並不消化脂質。"], ["題目限定化學性消化，必須有能改變脂質分子的相應酵素。", "膽汁只能協助乳化，水與紅血球更不是特定催化物質。"]),
  question("BIO_R4_Q_051_04", "BIO_R4_S051", "standard", "下列哪一組消化酵素與受質配對正確？", ["澱粉酵素－蛋白質", "蛋白質酵素－脂質", "脂質酵素－礦物質", "澱粉酵素－澱粉"], 3, ["澱粉酵素不適合蛋白質受質。", "蛋白質酵素不以脂質為主要受質。", "礦物質不需脂質酵素分解。", "澱粉酵素與澱粉受質配對正確。"], ["依酵素專一性，澱粉酵素催化澱粉分解，「澱粉酵素－澱粉」唯一正確。", "「澱粉酵素－蛋白質」、「蛋白質酵素－脂質」、「脂質酵素－礦物質」都將酵素與不同類別養分錯配，不能形成合理作用。"]),
  question("BIO_R4_Q_051_05", "BIO_R4_S051", "standard", "為何膽汁乳化能幫助脂質酵素作用？", ["增加脂質與酵素接觸的表面積", "使脂質酵素變成膽汁", "讓油滴直接進入血球", "把脂質全部轉成蛋白質"], 0, ["小油滴總表面積較大，利於酵素接觸。", "乳化不會改變酵素的物質種類。", "油滴不會直接進入紅血球內。", "脂質不會因乳化轉變成蛋白質。"], ["乳化的效益來自同量脂質分散後總表面積增加。", "「增加脂質與酵素接觸的表面積」能連結物理性分散與後續酵素作用，其他項目違反物質角色。"]),
  question("BIO_R4_Q_051_06", "BIO_R4_S051", "standard", "某消化液能分解蛋白質，最可能含有什麼？", ["只含清水", "適合蛋白質的消化酵素", "只含礦物質", "用於運氧的血紅素"], 1, ["清水本身不具蛋白質酵素的催化能力。", "相應酵素可使蛋白質發生化學性分解。", "礦物質不是蛋白質分解催化劑。", "血紅素位於血液，主要參與氧的運送。"], ["分解蛋白質表示有特定化學反應，最合理原因是含相應消化酵素。", "其他成分可能存在，但單獨不能解釋題幹的專一分解結果。"]),
  question("BIO_R4_Q_051_07", "BIO_R4_S051", "standard", "下列哪項最能區分膽汁與脂質酵素的作用？", ["兩者都直接形成胺基酸", "兩者都屬於紅血球成分", "膽汁乳化油滴，脂質酵素分解脂質分子", "膽汁分解澱粉，脂質酵素形成澱粉"], 2, ["胺基酸與蛋白質分解較直接相關。", "膽汁與消化酵素都不是紅血球成分。", "此項正確分開物理分散與化學分解。", "兩者都不負責所列澱粉作用。"], ["膽汁改變油滴分散狀態，脂質酵素才改變脂質分子。", "「膽汁乳化油滴，脂質酵素分解脂質分子」使用不同層次的判準，能精確區分兩者功能。"]),
  question("BIO_R4_Q_051_08", "BIO_R4_S051", "advanced", "蛋白質酵素加入澱粉後沒有產物，最合理的解釋為何？", ["澱粉完全不是養分", "所有酵素都失去功能", "澱粉已變成膽汁", "酵素與受質不符合專一性配對"], 3, ["澱粉是醣類養分的一種。", "單一錯配結果不能否定所有酵素功能。", "澱粉不會任意轉變為膽汁。", "蛋白質酵素不適合澱粉受質。"], ["已知酵素種類與受質不相符，無產物可由專一性直接解釋。", "「酵素與受質不符合專一性配對」最保守且符合資料，其他選項皆為過度或錯誤物質轉換。"]),
  question("BIO_R4_Q_051_09", "BIO_R4_S051", "advanced", "兩組都有脂質酵素，只有甲組先加膽汁，甲分解較快，最適當結論為何？", ["膽汁乳化可促進脂質酵素接觸受質", "膽汁把脂質酵素全部消耗", "乙組完全沒有脂質", "膽汁直接提供所有能量"], 0, ["乳化增加表面積，可解釋甲組較快。", "若酵素被耗盡，甲組不應分解更快。", "題幹明示兩組都有脂質受質。", "膽汁作用是乳化，不是能量來源。"], ["兩組主要差異是有無膽汁，甲較快支持乳化的間接促進作用。", "結論不能寫成膽汁是酵素或供能，只能描述接觸面積與速率。"]),
  question("BIO_R4_Q_051_10", "BIO_R4_S051", "advanced", "若油滴變小但脂質分子檢測不變，表示主要發生什麼？", ["脂質已完全吸收", "膽汁造成乳化而非化學分解", "脂質轉成蛋白質", "紅血球完成消化"], 1, ["油滴變小不能證明已穿過腸壁。", "外觀分散且分子不變符合乳化。", "沒有資料支持養分類別互相轉換。", "紅血球不在消化道內分解脂質。"], ["兩項證據是油滴尺度改變、分子種類不變，應判為物理性乳化。", "「膽汁造成乳化而非化學分解」準確限制作用，避免把油滴大小誤當脂質分子已被分解。"]),
  question("BIO_R4_Q_051_11", "BIO_R4_S051", "transfer", "製作模擬消化液時，若要分解澱粉應優先加入什麼？", ["蛋白質酵素", "膽汁", "澱粉酵素", "紅血球"], 2, ["蛋白質酵素的作用對象是蛋白質，無法完成本模型的澱粉分解目標。", "膽汁主要乳化脂質而不分解澱粉。", "澱粉酵素與目標受質配對。", "紅血球負責氣體運送而非消化。"], ["模擬設計應依受質選酵素，澱粉需要相應澱粉酵素。", "「澱粉酵素」符合專一性，「蛋白質酵素」、「膽汁」、「紅血球」的受質或生理功能皆不相符。"]),
  question("BIO_R4_Q_051_12", "BIO_R4_S051", "transfer", "若膽管阻塞使膽汁難以進入小腸，最直接受影響的協助作用為何？", ["唾液分解澱粉", "紅血球運送氧氣", "胃壁攪拌食物", "脂質乳化與後續酵素接觸"], 3, ["唾液作用發生在口腔，不依賴膽汁。", "運氧屬循環功能，不由膽汁控制。", "胃攪拌是胃壁肌肉作用。", "膽汁不足會減少油滴分散與接觸面。"], ["膽汁進入小腸的主要消化角色是乳化脂質，協助脂質酵素作用。", "「脂質乳化與後續酵素接觸」直接連結阻塞位置與膽汁功能，其他作用不靠膽汁完成。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S051", "BIO_R4_S051", "digestive-fluid-test",
  { title: "三種處理液測試", text: "研究者將等量脂質乳液分成三組，在相同溫度與時間下處理。甲加膽汁，乙加脂質酵素，丙先加膽汁再加脂質酵素。研究者分別記錄平均油滴大小與是否檢出脂質分解形成的小分子。", note: "油滴變小代表分散程度增加，小分子檢出才表示脂質分子發生化學分解。" },
  { summary: "表格比較膽汁、脂質酵素及兩者合用對油滴與小分子的影響。", colorIndependent: true, dataFallback: { columns: ["組別", "處理", "油滴", "小分子"], rows: [["甲", "膽汁", "變小", "未檢出"], ["乙", "脂質酵素", "變化較少", "檢出"], ["丙", "膽汁加脂質酵素", "變小", "檢出且較多"]] } },
  [
    question("BIO_R4_SQ_051_01", "BIO_R4_S051", "standard", "甲組油滴變小但未檢出小分子，最合理的判讀為何？", ["脂質轉變成蛋白質", "膽汁已完全分解脂質", "膽汁使脂質乳化", "甲組完成全部吸收"], 2, ["資料沒有養分類別轉換的證據。", "未檢出小分子反駁完全化學分解。", "油滴分散且分子未變符合乳化。", "容器實驗沒有腸壁可發生吸收。"], ["甲組只呈現油滴尺度改變，未出現化學分解產物。", "因此可判斷膽汁造成乳化，不能延伸為消化完成或吸收。"]),
    question("BIO_R4_SQ_051_02", "BIO_R4_S051", "advanced", "比較乙與丙，丙檢出較多小分子，最合理原因為何？", ["丙組沒有任何脂質", "乙組的酵素只負責運氧", "膽汁直接變成脂質酵素", "膽汁先增加油滴表面積，利於脂質酵素作用"], 3, ["丙組與乙組起始脂質量相同。", "脂質酵素的功能是催化脂質分解。", "膽汁與脂質酵素是不同物質。", "乳化可增加酵素與脂質的接觸面。"], ["兩組都有脂質酵素，丙多了先行膽汁乳化，結果小分子較多。", "「膽汁先增加油滴表面積，利於脂質酵素作用」以接觸面積解釋速率差異，沒有混淆膽汁與酵素角色。"]),
    question("BIO_R4_SQ_051_03", "BIO_R4_S051", "transfer", "若要確認膽汁本身不含脂質酵素，應增加哪個對照？", ["膽汁加經高溫失活的脂質酵素並測小分子", "把所有組的脂質移除", "只改用不同食物與溫度", "只觀察容器顏色"], 0, ["失活酵素下若仍無小分子可支持膽汁不催化。", "沒有脂質受質便無法檢驗分解。", "同時改兩項會讓結果難以解釋。", "容器顏色不能反映酵素活性。"], ["檢驗膽汁是否具有化學分解能力，需保留脂質並排除有效酵素。", "「膽汁加經高溫失活的脂質酵素並測小分子」建立相應比較，可把油滴分散與小分子形成清楚分開。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S052", "BIO_R4_S052",
  ["說明小腸構造如何增加吸收面積並縮短養分移動距離。", "連結絨毛內微血管與淋巴管到不同養分的後續運輸。"],
  [
    { id: "BIO_R4_L_S052_SEC_01", title: "長而有皺褶的管道", content: "小腸長度長，內壁又有環狀皺褶，可在有限腹腔空間中提供較大的接觸表面。增加的是整體內壁面積，不是讓食物停住不動，也不是使每個細胞無限變大。" },
    { id: "BIO_R4_L_S052_SEC_02", title: "絨毛進一步放大面積", content: "小腸內壁具有許多指狀絨毛，絨毛表面的細胞還有微小突起，使養分與腸壁接觸面積大幅增加。若絨毛受損，即使消化正常，吸收效率仍可能下降。" },
    { id: "BIO_R4_L_S052_SEC_03", title: "薄上皮縮短運輸距離", content: "絨毛表面上皮較薄，消化後的小分子通過屏障所需距離較短，有利於吸收。薄不等於完全沒有細胞，也不表示任何大分子都能不經消化直接穿過。" },
    { id: "BIO_R4_L_S052_SEC_04", title: "豐富管路帶走養分", content: "絨毛內有微血管與淋巴管，能接收穿過上皮的養分並運離小腸，維持吸收進行。葡萄糖、胺基酸多進入血液，脂質消化產物的運輸則與淋巴管較密切。" },
  ],
  [
    { id: "BIO_R4_L_S052_EX_01", prompt: "小腸內壁平滑或具有大量絨毛，何者吸收面積較大？", steps: ["比較相同長度內壁的表面起伏。", "判斷指狀突起增加的總表面積。"], answer: "具有大量絨毛者", why: "絨毛使原本平坦表面形成許多突起，在相同腸段內提供更多接觸位置，因此可提高養分吸收面積。" },
    { id: "BIO_R4_L_S052_EX_02", prompt: "絨毛上皮較薄對吸收有何直接幫助？", steps: ["辨認養分需由腸腔穿過上皮。", "比較屏障厚薄與移動距離。"], answer: "縮短養分穿過腸壁的距離", why: "消化後小分子穿越較薄上皮時路徑較短，有利於進入絨毛內管路；薄上皮不是增加酵素種類。" },
    { id: "BIO_R4_L_S052_EX_03", prompt: "絨毛內有大量微血管，對葡萄糖吸收後有何作用？", steps: ["確認葡萄糖已穿過上皮。", "連結微血管與物質運離小腸。"], answer: "接收並運送葡萄糖", why: "微血管可接收水溶性小分子並帶入循環，使吸收後的養分不在絨毛局部堆積，持續維持運輸。" },
  ],
  [
    { belief: "絨毛是小腸內寄生的生物。", whyWrong: "絨毛是小腸內壁本身形成的指狀構造，內含運輸管路。", correction: "把絨毛視為增加面積的腸壁構造，而非獨立生物。" },
    { belief: "小腸表面積大是因每個細胞都特別巨大。", whyWrong: "主要來自管道長、皺褶、絨毛與細胞表面微小突起的累積。", correction: "由多層次摺疊與突起解釋總面積，不用單一細胞大小解釋。" },
    { belief: "上皮越厚，養分越容易穿過。", whyWrong: "較厚屏障會增加移動距離，通常不利於快速吸收。", correction: "薄上皮縮短運輸距離，配合大面積與豐富管路提高效率。" },
    { belief: "所有養分都直接進入同一條血管。", whyWrong: "不同養分吸收後的初始運輸路徑不同，脂質與淋巴管較相關。", correction: "區分微血管與淋巴管角色，不把所有養分路徑簡化為相同。" },
  ],
  [
    { prompt: "絨毛最直接增加小腸的哪項條件？", answer: "吸收表面積", reason: "大量指狀突起使相同腸段具有更多與養分接觸的位置。" },
    { prompt: "薄上皮如何幫助養分吸收？", answer: "縮短移動距離", reason: "消化後小分子穿過較薄屏障時，需要移動的路徑較短。" },
    { prompt: "絨毛內微血管的主要作用為何？", answer: "接收並運送養分", reason: "微血管把吸收進入的水溶性養分帶入循環並運離小腸。" },
  ],
));

questions.push(
  question("BIO_R4_Q_052_01", "BIO_R4_S052", "foundation", "小腸內壁具有大量絨毛，最直接增加哪一項？", ["吸收表面積", "胃液酸度", "食道長度", "牙齒數量"], 0, ["絨毛突起能大幅增加小腸內壁表面積。", "胃液酸度由胃內環境決定。", "小腸絨毛不會改變食道長度。", "牙齒數量也不受小腸構造影響。"], ["絨毛是小腸壁的指狀突起，主要結構效益為增加接觸面。", "「胃液酸度」、「食道長度」、「牙齒數量」位於其他器官或屬不同條件，沒有直接因果關係。"]),
  question("BIO_R4_Q_052_02", "BIO_R4_S052", "foundation", "絨毛表面上皮較薄，對吸收最直接的幫助是什麼？", ["製造更多牙齒", "縮短養分移動距離", "使胃體積增加", "讓食物回到口腔"], 1, ["牙齒形成與小腸上皮無關。", "薄屏障可縮短小分子穿越腸壁的路徑。", "上皮厚度不會增加胃體積。", "正常消化道不會因上皮薄而逆流。"], ["養分需穿過上皮進入管路，較薄上皮表示移動距離較短。", "「縮短養分移動距離」直接連結構造與功能，其他項目皆屬無關器官或路徑。"]),
  question("BIO_R4_Q_052_03", "BIO_R4_S052", "foundation", "小腸絨毛內豐富的微血管，主要有何作用？", ["切碎食物", "分泌唾液", "接收並運送部分養分", "形成糞便"], 2, ["切碎食物主要靠口腔牙齒。", "唾液由唾液腺分泌到口腔。", "微血管能帶走吸收的水溶性養分。", "糞便形成主要與大腸後段相關。"], ["絨毛微血管位於吸收面下方，可接收小分子並送入循環。", "「接收並運送部分養分」符合血管運輸功能，其他選項分屬口腔或大腸作用。"]),
  question("BIO_R4_Q_052_04", "BIO_R4_S052", "standard", "下列哪組小腸構造與吸收功能配對正確？", ["絨毛－降低表面積", "厚上皮－縮短距離", "無血管－快速運送", "皺褶與絨毛－增加接觸面積"], 3, ["絨毛會增加而不是降低面積。", "厚上皮反而增加穿越距離。", "缺少管路不利於養分運離。", "多層次突起能增加總接觸表面。"], ["皺褶與絨毛讓有限長度的小腸擁有較大內壁面積。", "「皺褶與絨毛－增加接觸面積」構造與功能一致，其餘配對的方向皆相反。"]),
  question("BIO_R4_Q_052_05", "BIO_R4_S052", "standard", "若小腸絨毛大面積受損，最可能直接造成什麼？", ["養分吸收效率下降", "牙齒立刻脫落", "氣管無法送氣", "腎臟停止製尿"], 0, ["絨毛受損會減少有效吸收面積與管路。", "牙齒不由小腸絨毛維持。", "氣管送氣屬呼吸系統功能。", "腎臟製尿不會因絨毛受損直接停止。"], ["絨毛是小腸吸收的重要結構，受損最直接影響養分進入循環。", "其他器官可能受長期營養影響，但不是題目所問直接結果。"]),
  question("BIO_R4_Q_052_06", "BIO_R4_S052", "standard", "小腸很長且內壁多皺褶，兩項特徵共同帶來什麼優勢？", ["讓食物完全不移動", "提供較大的消化吸收表面", "把小腸變成實心器官", "阻止所有養分接近腸壁"], 1, ["小腸仍需推送內容物前進。", "長度與皺褶共同增加內壁接觸面。", "小腸仍是具有管腔的器官。", "大面積反而增加養分接觸機會。"], ["兩個構造特徵都能在腹腔中增加食物與腸壁接觸的總面積。", "「提供較大的消化吸收表面」同時解釋兩項特徵，其他選項與管道及吸收作用相反。"]),
  question("BIO_R4_Q_052_07", "BIO_R4_S052", "standard", "葡萄糖穿過小腸上皮後，最可能先進入哪種構造？", ["食道管腔", "肺泡", "絨毛內微血管", "胃腔"], 2, ["食道位於小腸之前且不是吸收後路徑。", "肺泡只進行呼吸氣體交換。", "水溶性葡萄糖可進入絨毛微血管。", "胃腔也位於小腸之前。"], ["葡萄糖是消化後可吸收的小分子，穿過上皮後由微血管接收。", "「絨毛內微血管」符合位置與運輸方向，其餘構造不在吸收界面。"]),
  question("BIO_R4_Q_052_08", "BIO_R4_S052", "advanced", "比較平滑管與同長度多絨毛管，後者吸收較多，最合理原因為何？", ["絨毛使每個養分變重", "絨毛讓上皮完全消失", "絨毛製造所有消化酵素", "絨毛增加可吸收的表面積"], 3, ["結構不會改變養分分子重量。", "絨毛表面仍由上皮細胞構成。", "絨毛主要不是製造全部酵素。", "突起使同長度管道接觸面更大。"], ["公平比較只改變表面形態，吸收增加應由接觸面積差異解釋。", "「絨毛增加可吸收的表面積」符合構造功能關係，其他選項都誇大或扭曲絨毛作用。"]),
  question("BIO_R4_Q_052_09", "BIO_R4_S052", "advanced", "絨毛內管路若阻塞，即使上皮正常，吸收仍可能下降，原因為何？", ["養分無法有效運離吸收位置", "小腸會立刻變成胃", "牙齒無法咀嚼食物", "膽汁會停止由肝臟製造"], 0, ["運輸受阻會使已吸收養分在局部累積。", "管路阻塞不會改變器官種類。", "口腔咀嚼不由絨毛管路控制。", "肝臟製膽汁也不是直接結果。"], ["吸收不只需穿過上皮，還需管路持續帶走養分。", "「養分無法有效運離吸收位置」說明運輸與吸收連續配合，其他器官功能沒有直接關係。"]),
  question("BIO_R4_Q_052_10", "BIO_R4_S052", "advanced", "下列哪個證據最支持絨毛增加表面積而非增加腸長？", ["小腸內有消化液", "相同腸段展開後表面積較平滑模型大", "食物可由胃進小腸", "大腸位於小腸之後"], 1, ["消化液存在不能量化絨毛表面積。", "相同長度下展開面積較大直接支持突起效果。", "器官路徑不涉及表面積比較。", "先後位置也不能證明面積來源。"], ["控制腸段長度後，表面積仍較大，差異即可歸因於絨毛突起。", "「相同腸段展開後表面積較平滑模型大」提供直接幾何比較，其他敘述只是消化系統的一般事實。"]),
  question("BIO_R4_Q_052_11", "BIO_R4_S052", "transfer", "設計人工吸收膜時，哪種構造最能模仿小腸絨毛優勢？", ["厚而完全平滑的膜", "沒有任何流動管路", "薄膜形成許多突起且下方有流動管路", "只增加容器外部重量"], 2, ["厚平滑會減少面積並增加距離。", "缺少管路不利於移除穿膜物質。", "此設計同時提供大面積、短距離與運輸。", "外部重量不會提高膜吸收效率。"], ["模仿需同時抓住絨毛的突起、薄上皮與內部運輸三項特徵。", "「薄膜形成許多突起且下方有流動管路」完整重現構造功能，其他設計都缺少關鍵條件。"]),
  question("BIO_R4_Q_052_12", "BIO_R4_S052", "transfer", "某藥物讓絨毛變平但不影響消化酵素，最可能觀察到什麼？", ["食物完全不能被分解", "胃立刻停止攪拌", "唾液無法分泌", "小分子形成正常但吸收量減少"], 3, ["酵素正常表示化學分解仍可進行。", "絨毛變平不直接控制胃肌肉。", "唾液腺也不由小腸絨毛控制。", "面積下降會使已形成小分子較難充分吸收。"], ["題幹分開消化與吸收，酵素正常保留小分子形成，絨毛平坦降低吸收。", "「小分子形成正常但吸收量減少」同時符合兩個限定，其他選項錯把小腸構造影響擴張到別處。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S052", "BIO_R4_S052", "surface-area-model",
  { title: "三種吸收膜模型", text: "學生製作相同材質與厚度的人工膜，甲膜平坦，乙膜有少量皺褶，丙膜有密集指狀突起。三膜投影面積相同，接觸相同濃度溶液十分鐘後，測量穿膜物質量。", note: "模型只比較表面形態，不代表完整小腸所有生理作用。" },
  { summary: "表格比較平坦、皺褶與指狀突起膜的實際表面積及穿膜量。", colorIndependent: true, dataFallback: { columns: ["模型", "表面形態", "實際表面積", "穿膜量"], rows: [["甲", "平坦", "100平方公分", "8毫克"], ["乙", "少量皺褶", "160平方公分", "13毫克"], ["丙", "密集指狀突起", "280平方公分", "22毫克"]] } },
  [
    question("BIO_R4_SQ_052_01", "BIO_R4_S052", "standard", "哪一個模型最接近小腸絨毛增加表面積的特徵？", ["甲模型的平坦表面", "丙模型的密集指狀突起", "乙模型的少量皺褶", "甲、乙兩模型的表面積總和"], 1, ["甲膜平坦，缺少絨毛式突起，實際表面積也最小。", "丙具有密集指狀突起且表面積最大，最接近絨毛形態。", "乙只有少量皺褶，形態與表面積都不如丙接近密集絨毛。", "題目比較單一膜的表面形態，合併兩膜面積不能代表一個絨毛模型。"], ["小腸絨毛是大量指狀突起，丙模型的結構描述最相近。", "實際表面積數據也支持丙比同投影面積的其他模型更大。"]),
    question("BIO_R4_SQ_052_02", "BIO_R4_S052", "advanced", "三個模型的結果最支持哪項構造功能關係？", ["表面積越大，穿膜量必定為零", "平坦膜會製造更多酵素", "突起增加表面積並提高穿膜量", "膜越皺，材質一定不同"], 2, ["資料顯示表面積增加時穿膜量上升。", "實驗沒有測量任何酵素製造。", "丙的表面積與穿膜量皆為最高。", "題幹明示三膜材質與厚度相同。"], ["在材質、厚度與投影面積相同下，突起越多的模型穿膜量越高。", "「突起增加表面積並提高穿膜量」是資料支持的關係，不能延伸為材質差異或酵素作用。"]),
    question("BIO_R4_SQ_052_03", "BIO_R4_S052", "transfer", "若要再模仿絨毛內微血管功能，模型應增加什麼？", ["更厚的不透膜", "停止膜下所有流動", "把溶液改成固體石塊", "膜下持續流動並帶走穿膜物質的管路"], 3, ["不透厚膜會阻礙物質穿越。", "停止流動不能模擬養分運離。", "固體石塊不適合作為吸收溶液模型。", "流動管路可接收並帶走已穿膜物質。"], ["微血管功能是接收並運輸吸收物，因此模型需有膜下流動管路。", "「膜下持續流動並帶走穿膜物質的管路」補上運輸功能，與原模型的表面積比較形成完整模擬。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S053", "BIO_R4_S053",
  ["區分消化、吸收與排遺三個連續但不同的過程。", "由物質位置與是否經細胞代謝判斷食物殘餘的去向。"],
  [
    { id: "BIO_R4_L_S053_SEC_01", title: "消化把大分子變小", content: "消化包含物理性處理與化學性分解，目的是讓食物中的大分子成為較小、可被吸收的形式。物質仍在消化道腔內時，即使已分解，也尚未完成吸收。" },
    { id: "BIO_R4_L_S053_SEC_02", title: "吸收跨越腸壁", content: "吸收是消化後的小分子、水或部分其他物質穿過消化道壁，進入血液或淋巴的過程。判斷關鍵是跨過腸壁，不是食物只要進入小腸就自動算吸收。" },
    { id: "BIO_R4_L_S053_SEC_03", title: "排遺排出食物殘餘", content: "未被消化或吸收的食物殘餘進入大腸，部分水分再被吸收，最後形成糞便由肛門排出，稱為排遺。這些殘餘大多沒有先進入細胞代謝。" },
    { id: "BIO_R4_L_S053_SEC_04", title: "排遺不等於排泄", content: "排泄是排除細胞代謝產生的廢物，例如二氧化碳或含氮廢物；排遺則是把消化道中未利用的食物殘餘排出。兩者都離開身體，但物質來源與路徑不同。" },
  ],
  [
    { id: "BIO_R4_L_S053_EX_01", prompt: "澱粉在小腸被酵素分解成小分子，屬於哪個過程？", steps: ["辨認分子由大變小。", "確認尚未描述穿過腸壁。"], answer: "消化", why: "題幹只描述化學分解，物質仍可位於腸腔中；沒有進入血液或淋巴的證據，因此是消化而非吸收。" },
    { id: "BIO_R4_L_S053_EX_02", prompt: "葡萄糖由小腸腔穿過上皮進入微血管，屬於什麼？", steps: ["追蹤葡萄糖跨越小腸壁。", "確認終點進入微血管。"], answer: "吸收", why: "葡萄糖已完成消化形成小分子，接著穿過腸壁進入循環，符合吸收的空間與方向判準。" },
    { id: "BIO_R4_L_S053_EX_03", prompt: "未消化纖維隨糞便由肛門排出，屬於什麼？", steps: ["確認物質是食物殘餘。", "辨認排出路徑為消化道末端。"], answer: "排遺", why: "未消化纖維沒有先成為細胞代謝廢物，而是沿消化道形成糞便後排出，因此屬排遺。" },
  ],
  [
    { belief: "食物進入小腸就等於完成吸收。", whyWrong: "養分仍需先形成適合的小分子並穿過小腸壁進入管路。", correction: "以跨越腸壁為吸收判準，不只看食物所在器官。" },
    { belief: "消化與吸收是完全相同的過程。", whyWrong: "消化改變食物形態或分子，吸收則改變養分所在空間。", correction: "先判斷是否分解，再判斷是否穿過腸壁進入循環。" },
    { belief: "糞便全部都是細胞代謝產生的廢物。", whyWrong: "糞便主要含未消化吸收的食物殘餘、水與其他消化道內容物。", correction: "把糞便歸為排遺材料，代謝廢物則由肺、腎等排泄途徑處理。" },
    { belief: "只要物質離開身體就都叫排遺。", whyWrong: "二氧化碳與含氮廢物來自代謝，屬排泄而非食物殘餘。", correction: "依物質來源與排出路徑區分排遺和排泄，不只看最終離體。" },
  ],
  [
    { prompt: "蛋白質被酵素分解屬於什麼？", answer: "消化", reason: "大分子轉變為較小分子，是化學性消化而尚非跨壁吸收。" },
    { prompt: "葡萄糖進入小腸微血管屬於什麼？", answer: "吸收", reason: "葡萄糖穿過腸壁並進入循環管路，符合吸收的方向判準。" },
    { prompt: "糞便由肛門排出屬於什麼？", answer: "排遺", reason: "未利用食物殘餘沿消化道末端排出，並非細胞代謝廢物。" },
  ],
));

questions.push(
  question("BIO_R4_Q_053_01", "BIO_R4_S053", "foundation", "消化酵素把大分子養分變成小分子，這屬於什麼過程？", ["消化", "吸收", "排遺", "排泄"], 0, ["分子被分解是化學性消化的核心。", "吸收需描述物質穿過消化道壁。", "排遺是排出未利用的食物殘餘。", "排泄處理的是細胞代謝廢物。"], ["題幹提供分子由大變小的證據，直接符合消化。", "沒有跨壁、糞便或代謝廢物資訊，因此「吸收」、「排遺」、「排泄」都不成立。"]),
  question("BIO_R4_Q_053_02", "BIO_R4_S053", "foundation", "小分子養分穿過小腸壁進入血液，稱為什麼？", ["消化", "吸收", "排遺", "咀嚼"], 1, ["小分子已形成，題幹重點不是再分解。", "跨越腸壁進入血液就是吸收。", "排遺不會讓養分進入循環。", "咀嚼發生在口腔並改變顆粒大小。"], ["吸收的操作判準是從消化道腔跨過腸壁進入體內管路。", "「吸收」與方向及終點完全一致，其他選項的作用位置不同。"]),
  question("BIO_R4_Q_053_03", "BIO_R4_S053", "foundation", "未被消化的食物殘餘最後由肛門排出，屬於什麼？", ["吸收", "細胞呼吸", "排遺", "氣體交換"], 2, ["物質沒有穿過腸壁進入循環。", "細胞呼吸利用養分釋放能量。", "食物殘餘由消化道末端排出是排遺。", "氣體交換涉及氧與二氧化碳。"], ["題幹明示未消化殘餘與肛門排出，兩者共同指向排遺。", "「吸收」、「細胞呼吸」、「氣體交換」沒有沿消化道末端排出食物殘餘的作用。"]),
  question("BIO_R4_Q_053_04", "BIO_R4_S053", "standard", "下列哪一項最能表示吸收而不是消化？", ["牙齒把食物磨碎", "酵素分解澱粉", "胃攪拌食物", "葡萄糖進入絨毛微血管"], 3, ["磨碎屬物理性消化。", "澱粉分解屬化學性消化。", "胃攪拌仍是物理性消化。", "跨越腸壁進入微血管是吸收。"], ["「葡萄糖進入絨毛微血管」描述小分子由腸腔進入循環，符合吸收。", "「牙齒把食物磨碎」、「酵素分解澱粉」、「胃攪拌食物」都在改變食物外形或分子，仍屬消化階段。"]),
  question("BIO_R4_Q_053_05", "BIO_R4_S053", "standard", "糞便中的未消化纖維主要如何離開人體？", ["經排遺由肛門排出", "經肺泡呼出", "經腎臟形成尿液", "進入血液後消失"], 0, ["纖維殘餘沿大腸到肛門排出。", "肺泡只排出呼吸相關氣體。", "腎臟處理血液中的代謝廢物與水鹽。", "未消化纖維不會先進入血液。"], ["食物殘餘留在消化道內，最後形成糞便經肛門排遺。", "其他途徑處理氣體或血液成分，與纖維殘餘位置不符。"]),
  question("BIO_R4_Q_053_06", "BIO_R4_S053", "standard", "消化與吸收最主要的差別是什麼？", ["兩者發生器官必定完全不同", "消化改變食物，吸收使養分跨越腸壁", "吸收只把食物切小", "消化一定讓物質進入血液"], 1, ["兩者可在小腸前後相連發生。", "此項正確區分物質轉變與空間移動。", "切小屬物理性消化而非吸收。", "進入血液是吸收，不是消化定義。"], ["消化回答食物如何被分解，吸收回答小分子如何進入體內管路。", "「消化改變食物，吸收使養分跨越腸壁」以不同判準區分，避免只用器官位置判斷。"]),
  question("BIO_R4_Q_053_07", "BIO_R4_S053", "standard", "哪項敘述正確區分排遺與排泄？", ["兩者都只排出糞便", "兩者都只由腎臟完成", "排遺排食物殘餘，排泄排代謝廢物", "排遺會讓養分進入血液"], 2, ["排泄還包含二氧化碳等代謝廢物。", "排遺由消化道末端完成，不只腎臟。", "此項依物質來源正確區分兩者。", "進入血液屬吸收而不是排遺。"], ["判別重點是排出物來源：未利用食物殘餘對代謝廢物。", "「排遺排食物殘餘，排泄排代謝廢物」同時給出兩者正確對照，其他敘述都混淆器官或方向。"]),
  question("BIO_R4_Q_053_08", "BIO_R4_S053", "advanced", "某分子已在小腸形成但仍留在腸腔，最適當的判斷為何？", ["已完成吸收", "已完成排遺", "已進入血液循環", "可能已完成消化但尚未吸收"], 3, ["仍在腸腔表示尚未跨越腸壁。", "排遺需由消化道末端排出體外。", "題幹明示沒有離開腸腔。", "形成小分子可代表消化，但位置顯示未吸收。"], ["分子狀態與所在位置需分開判斷，小分子已形成但尚在腸腔。", "「可能已完成消化但尚未吸收」同時符合消化完成與吸收未發生，沒有概念衝突。"]),
  question("BIO_R4_Q_053_09", "BIO_R4_S053", "advanced", "某物質先穿過小腸上皮，後出現在肝門靜脈，最能表示什麼？", ["此物質已被吸收進入血液", "此物質正在口腔咀嚼", "此物質形成糞便", "此物質由肺泡排出"], 0, ["跨上皮並進入靜脈符合吸收路徑。", "口腔位置與題幹小腸血管不符。", "形成糞便的物質不會先進入靜脈。", "肺泡排氣也不經小腸上皮。"], ["跨越小腸壁後進入血液，是吸收完成的直接空間證據。", "「此物質已被吸收進入血液」可由兩個位置連續推出，其他選項分屬不同器官與方向。"]),
  question("BIO_R4_Q_053_10", "BIO_R4_S053", "advanced", "若大分子消化正常但小腸上皮受損，哪個過程最直接下降？", ["咀嚼", "吸收", "吞嚥", "胃攪拌"], 1, ["牙齒咀嚼不依賴小腸上皮。", "上皮受損會妨礙小分子跨越腸壁。", "吞嚥發生在咽與食道前段。", "胃攪拌由胃壁肌肉完成。"], ["題幹保留消化正常，唯一受小腸上皮直接影響的是吸收。", "「吸收」依受損位置判斷，其餘功能位於消化道其他部位。"]),
  question("BIO_R4_Q_053_11", "BIO_R4_S053", "transfer", "追蹤口服標記葡萄糖，在哪裡出現可作為已吸收的證據？", ["仍在小腸腔內", "附著在牙齒表面", "出現在絨毛微血管中", "停留在胃內容物中"], 2, ["仍在腸腔尚未跨越吸收屏障。", "牙齒表面位於攝入與咀嚼階段。", "微血管位置表示已穿過小腸壁。", "胃內容物也仍在消化道管腔。"], ["要證明吸收，標記物必須由腸腔進入體內循環管路。", "「出現在絨毛微血管中」提供跨壁後位置，其他選項都仍在消化道內或入口處。"]),
  question("BIO_R4_Q_053_12", "BIO_R4_S053", "transfer", "便祕時糞便停留大腸較久，最可能與哪項作用增加有關？", ["蛋白質全部變成葡萄糖", "氧氣進入紅血球", "食物回到口腔", "大腸吸收較多水分"], 3, ["大腸停留不會使蛋白質全部轉換。", "運氧發生在肺與血液循環。", "正常路徑不會由大腸回到口腔。", "停留較久可使更多水分被大腸吸收。"], ["大腸具有吸收部分水分的功能，停留時間增加可使糞便更乾硬。", "「大腸吸收較多水分」符合器官功能與生活情境，其他選項跨越無關系統。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S053", "BIO_R4_S053", "tracer-route",
  { title: "三種標記物追蹤", text: "研究者追蹤三種標記物：甲是澱粉分解後的小分子，出現在小腸微血管；乙是未消化植物纖維，最後出現在糞便；丙是細胞代謝產生的二氧化碳，最後由肺呼出。", note: "標記只表示物質所在位置，不改變原本生理作用。" },
  { summary: "表格列出三種標記物的來源與最後觀察位置。", colorIndependent: true, dataFallback: { columns: ["標記", "來源", "觀察位置"], rows: [["甲", "澱粉分解後小分子", "小腸微血管"], ["乙", "未消化植物纖維", "糞便"], ["丙", "細胞代謝二氧化碳", "呼出氣"]] } },
  [
    question("BIO_R4_SQ_053_01", "BIO_R4_S053", "standard", "甲標記物出現在小腸微血管，表示已發生哪個過程？", ["吸收", "排遺", "咀嚼", "排泄"], 0, ["小分子跨腸壁進入微血管就是吸收。", "排遺不會讓物質進入血液。", "咀嚼發生在口腔且只改變顆粒。", "甲不是細胞代謝產生的廢物。"], ["甲由小腸腔進入微血管，跨越位置是判斷吸收的直接證據。", "其餘過程的物質來源或作用位置都與紀錄不相符。"]),
    question("BIO_R4_SQ_053_02", "BIO_R4_S053", "advanced", "乙與丙都離開人體，為何過程分類不同？", ["乙是氣體而丙是固體", "乙是食物殘餘，丙是代謝廢物", "乙經血液而丙經小腸", "兩者其實都只屬吸收"], 1, ["乙是纖維而丙是氣體，但判準在來源。", "來源分別對應排遺與排泄。", "題幹沒有乙先進入血液的路徑。", "兩者都在排出，不是進入體內管路。"], ["乙未被消化吸收，沿消化道排遺；丙由細胞代謝產生並經肺排泄。", "「乙是食物殘餘，丙是代謝廢物」用來源判斷，不只按物態或是否離開身體分類。"]),
    question("BIO_R4_SQ_053_03", "BIO_R4_S053", "transfer", "若甲只在小腸腔中被檢出，尚未進入微血管，應如何判斷？", ["已完成排泄", "已完成排遺", "可能完成消化但尚未證明吸收", "已成為細胞代謝廢物"], 2, ["甲不是由肺腎等排出的代謝廢物。", "仍在小腸腔中也尚未由肛門排出。", "小分子已形成，但沒有跨腸壁證據。", "來源是澱粉分解而非細胞代謝。"], ["判讀需同時看分子狀態與位置：形成小分子可支持消化，留在腔內未支持吸收。", "「可能完成消化但尚未證明吸收」保留證據界線，沒有把尚未發生的跨壁運輸先行認定。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S054", "BIO_R4_S054",
  ["追蹤養分由食物經消化吸收進入循環並送達細胞的路徑。", "區分葡萄糖、胺基酸進入微血管與脂質消化產物進入淋巴管的初始路徑。"],
  [
    { id: "BIO_R4_L_S054_SEC_01", title: "食物先在消化道處理", content: "攝入的食物先經口腔、胃與小腸等處的物理、化學性消化。醣類、蛋白質與脂質等大分子需形成適合吸收的較小成分，才能有效穿過小腸上皮。" },
    { id: "BIO_R4_L_S054_SEC_02", title: "吸收是進入體內管路的關口", content: "消化後的小分子由小腸腔穿過絨毛上皮，進入微血管或淋巴管。跨越腸壁後才算真正由消化道內容物進入體內運輸系統，不能把停留腸腔誤認為已送達細胞。" },
    { id: "BIO_R4_L_S054_SEC_03", title: "水溶性養分進入血液", content: "葡萄糖、胺基酸等多先進入絨毛微血管，隨血液經肝臟等處再送往全身。血液的角色是運輸，不會替代小腸酵素完成所有大分子消化。" },
    { id: "BIO_R4_L_S054_SEC_04", title: "脂質與淋巴路徑", content: "部分脂質消化產物在小腸細胞處理後進入絨毛內淋巴管，再匯入血液循環。無論初始進血或淋巴，養分最終都需由循環運送到需要的細胞。" },
  ],
  [
    { id: "BIO_R4_L_S054_EX_01", prompt: "葡萄糖在小腸被吸收後，下一個直接位置通常是哪裡？", steps: ["確認葡萄糖是水溶性小分子。", "追蹤它穿過絨毛上皮後的管路。"], answer: "絨毛微血管", why: "葡萄糖穿過小腸上皮後先進入絨毛微血管，再由血液帶往肝臟與全身，並非直接跳到任意細胞。" },
    { id: "BIO_R4_L_S054_EX_02", prompt: "標記脂質先出現在絨毛淋巴管，能否說它未被吸收？", steps: ["辨認淋巴管位於腸壁內側。", "以是否跨越腸壁判斷吸收。"], answer: "不能，進入淋巴管已表示吸收", why: "吸收不限於進入血管；脂質相關成分跨過小腸上皮並進入淋巴管，同樣已離開腸腔進入體內管路。" },
    { id: "BIO_R4_L_S054_EX_03", prompt: "食物大分子仍在小腸腔中，是否已到達全身細胞？", steps: ["確認物質尚未穿過腸壁。", "檢查是否已進入循環運輸。"], answer: "尚未", why: "留在腸腔的大分子仍屬消化道內容物，需先完成消化、吸收並進入循環，才可能被運送到全身細胞。" },
  ],
  [
    { belief: "食物一吞下就直接進入血液。", whyWrong: "食物先沿消化道移動，大分子還需消化並穿過小腸壁。", correction: "依序寫出消化道處理、小腸吸收與循環運送，不跳過步驟。" },
    { belief: "所有養分都只由微血管進入循環。", whyWrong: "脂質相關成分的初始吸收運輸與絨毛淋巴管較密切。", correction: "水溶性養分先進微血管，脂質可先進淋巴再匯入血液。" },
    { belief: "養分進入小腸就表示已送到細胞。", whyWrong: "仍在小腸腔內尚未吸收，跨壁後還需循環運送到組織。", correction: "用所在空間追蹤腸腔、腸壁管路、循環與細胞四個階段。" },
    { belief: "血液能直接把完整澱粉送進細胞利用。", whyWrong: "澱粉需先被消化為可吸收小分子，才能進入血液運送。", correction: "大分子先消化，小分子再吸收與運輸，不能顛倒順序。" },
  ],
  [
    { prompt: "葡萄糖吸收後先進入絨毛何種管路？", answer: "微血管", reason: "葡萄糖穿過上皮後由絨毛微血管接收並進入血液循環。" },
    { prompt: "脂質相關成分可先進入哪種管路？", answer: "淋巴管", reason: "部分脂質消化產物吸收後先進淋巴，再匯入血液循環。" },
    { prompt: "養分由小腸到細胞還需要哪個系統？", answer: "循環系統", reason: "血液與淋巴把已吸收養分運離小腸並送往全身組織。" },
  ],
));

questions.push(
  question("BIO_R4_Q_054_01", "BIO_R4_S054", "foundation", "食物中的大分子養分進入循環前，通常先要完成什麼？", ["消化成較小分子", "由肺泡吸入", "變成糞便", "由腎臟製成尿液"], 0, ["大分子需先分解成可吸收形式。", "肺泡只讓呼吸氣體進出血液。", "成為糞便表示未被充分利用。", "尿液處理的是血液中需排出的物質。"], ["消化讓大分子成為可穿過小腸壁的小分子，是進入循環前提。", "其餘途徑分屬呼吸、排遺或排泄，與養分吸收方向不符。"]),
  question("BIO_R4_Q_054_02", "BIO_R4_S054", "foundation", "葡萄糖穿過小腸絨毛上皮後，通常先進入哪裡？", ["小腸腔", "絨毛微血管", "胃腔", "食道"], 1, ["穿過上皮代表已離開小腸腔。", "微血管接收葡萄糖並帶入循環。", "胃位於小腸之前，不是吸收後路徑。", "食道更位於消化道前段。"], ["葡萄糖是水溶性小分子，吸收後由絨毛微血管接收。", "「絨毛微血管」符合跨壁後位置，「小腸腔」、「胃腔」、「食道」都仍是消化道管腔。"]),
  question("BIO_R4_Q_054_03", "BIO_R4_S054", "foundation", "部分脂質消化產物吸收後，最先與哪種管路較密切？", ["氣管", "尿道", "絨毛淋巴管", "食道"], 2, ["氣管運送空氣而非脂質養分。", "尿道負責尿液排出。", "脂質相關成分可先進入絨毛淋巴管。", "食道只推送食團到胃。"], ["小腸絨毛淋巴管是部分脂質成分吸收後的初始運輸路徑。", "「絨毛淋巴管」位於吸收面內，其他管道屬呼吸、泌尿或消化前段。"]),
  question("BIO_R4_Q_054_04", "BIO_R4_S054", "standard", "下列哪個順序最符合葡萄糖由食物到細胞的路徑？", ["細胞→小腸腔→口腔", "肺泡→胃→血液", "大腸→食道→細胞", "消化→小腸吸收→血液運送→細胞"], 3, ["此順序把正常方向完全倒轉。", "葡萄糖不需由肺泡進入胃。", "大腸與食道順序也不連續。", "此項依序呈現分解、跨壁與循環運輸。"], ["食物養分需先消化，再由小腸吸收進血，最後送達細胞。", "「消化→小腸吸收→血液運送→細胞」是唯一包含必要階段且方向正確的完整路徑。"]),
  question("BIO_R4_Q_054_05", "BIO_R4_S054", "standard", "若葡萄糖仍在小腸腔中，可直接判斷它已送到全身細胞嗎？", ["不能，尚需吸收與循環運送", "可以，進小腸等於進血液", "可以，小腸腔就是微血管", "不能，葡萄糖只能形成糞便"], 0, ["位置仍在腸腔，尚未跨壁進入循環。", "小腸腔與血液是不同空間。", "微血管位於絨毛內而不等同腸腔。", "葡萄糖可被吸收，不是只能排遺。"], ["判斷路徑要看物質所在空間，腸腔中的葡萄糖仍未完成吸收。", "「不能，尚需吸收與循環運送」正確指出後續兩步，其他敘述混淆空間或否定吸收。"]),
  question("BIO_R4_Q_054_06", "BIO_R4_S054", "standard", "血液在養分由小腸到細胞的過程中主要負責什麼？", ["把所有大分子消化", "運送已吸收的養分", "在口腔咀嚼食物", "形成未消化糞便"], 1, ["大分子消化主要在消化道由酵素完成。", "血液可把已吸收養分送往組織。", "咀嚼由牙齒與口腔肌肉完成。", "糞便形成主要位於大腸。"], ["養分跨小腸壁後需要循環系統分配到全身，血液負責運輸。", "「運送已吸收的養分」符合路徑位置，其他功能分別屬消化前段或排遺。"]),
  question("BIO_R4_Q_054_07", "BIO_R4_S054", "standard", "哪項最能證明某養分已由小腸完成吸收？", ["仍停在小腸腔中", "食物已被牙齒切小", "在絨毛內微血管或淋巴管檢出", "出現在餐盤上"], 2, ["留在腸腔表示尚未跨越上皮。", "切小只代表物理性消化。", "進入管路表示已穿過小腸壁。", "餐盤上的食物尚未被攝入。"], ["吸收的直接判準是由消化道腔跨壁進入體內運輸管路。", "「在絨毛內微血管或淋巴管檢出」提供跨壁後位置，其他位置都在吸收之前。"]),
  question("BIO_R4_Q_054_08", "BIO_R4_S054", "advanced", "標記脂質先出現在淋巴，之後出現在血液，最合理解釋為何？", ["脂質從未被吸收", "血液變成小腸腔", "淋巴只負責排遺", "脂質可先走淋巴再匯入血液"], 3, ["進入淋巴已表示跨壁吸收。", "兩個空間不會互相變成對方。", "淋巴參與運輸而不是糞便排出。", "時間先後符合脂質初始運輸路徑。"], ["脂質相關成分可由絨毛淋巴管接收，之後匯入血液循環。", "「脂質可先走淋巴再匯入血液」同時解釋兩個時間點，沒有否定已觀察到的吸收。"]),
  question("BIO_R4_Q_054_09", "BIO_R4_S054", "advanced", "若小腸吸收正常但循環受阻，最可能出現什麼情況？", ["養分已跨腸壁但難以有效送到組織", "食物無法進入口腔", "牙齒立即失去咀嚼功能", "胃液完全不再分泌"], 0, ["吸收後仍需循環把養分分配到細胞。", "攝食入口不由循環受阻直接決定。", "牙齒咀嚼也不是直接結果。", "胃液分泌與此假設沒有必然關係。"], ["題幹將吸收與運輸分開，循環受阻直接影響吸收後的配送。", "「養分已跨腸壁但難以有效送到組織」符合連續路徑，「食物無法進入口腔」、「牙齒立即失去咀嚼功能」、「胃液完全不再分泌」位於吸收前且缺乏直接因果。"]),
  question("BIO_R4_Q_054_10", "BIO_R4_S054", "advanced", "完整澱粉為何通常不能直接由血液送入細胞使用？", ["澱粉一定是礦物質", "需先消化為可吸收的小分子", "血液完全不能運送養分", "細胞只利用脂質"], 1, ["澱粉屬於醣類而非礦物質。", "大分子需先分解並跨越小腸壁。", "血液能運送多種已吸收養分。", "細胞也可利用葡萄糖等養分。"], ["問題在分子大小與吸收條件，澱粉需先被消化成較小分子。", "「需先消化為可吸收的小分子」符合消化吸收路徑，其他選項錯誤分類或使用絕對否定。"]),
  question("BIO_R4_Q_054_11", "BIO_R4_S054", "transfer", "口服藥物要經小腸吸收後作用全身，哪個步驟不可缺少？", ["由肛門先排出", "進入食道後立刻作用所有細胞", "穿過小腸壁並由循環運送", "先進入肺泡交換氣體"], 2, ["排出體外後無法再由腸道吸收。", "食道只運送，尚未進入循環。", "跨壁與循環是到達全身的必要路徑。", "口服藥不需先進肺泡。"], ["要從消化道到全身組織，藥物需吸收進入體內管路並隨循環配送。", "「穿過小腸壁並由循環運送」包含兩個必要階段，其他選項方向或器官皆不正確。"]),
  question("BIO_R4_Q_054_12", "BIO_R4_S054", "transfer", "若絨毛微血管被阻斷，哪種物質的初始運輸最直接受影響？", ["氣管內氧氣", "大腸內糞便", "口腔內食團", "小腸吸收的葡萄糖"], 3, ["氣管氧氣不經小腸微血管。", "糞便留在大腸管腔而非絨毛血管。", "食團仍位於口腔消化前段。", "葡萄糖吸收後需進入絨毛微血管。"], ["絨毛微血管直接接收葡萄糖等水溶性小分子，阻斷會影響其運離。", "「小腸吸收的葡萄糖」符合管路位置與養分種類，其他物質都不走此路徑。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S054", "BIO_R4_S054", "nutrient-tracer",
  { title: "兩種養分標記的出現順序", text: "受試模型的小腸腔同時加入標記葡萄糖與標記脂質消化產物。研究者記錄兩種標記最先出現的管路，以及十分鐘後是否進入血液。模型保留正常絨毛微血管與淋巴管。", note: "最先出現位置用來比較初始吸收路徑，並非表示最後只停留該處。" },
  { summary: "表格列出葡萄糖與脂質標記最先出現位置及後續血液檢出結果。", colorIndependent: true, dataFallback: { columns: ["標記物", "最先出現位置", "十分鐘後血液"], rows: [["葡萄糖", "絨毛微血管", "檢出"], ["脂質消化產物", "絨毛淋巴管", "檢出"]] } },
  [
    question("BIO_R4_SQ_054_01", "BIO_R4_S054", "standard", "標記葡萄糖最先出現在微血管，代表它已完成什麼？", ["由腎臟形成尿液", "由大腸形成糞便", "由肺泡進入氣管", "由小腸吸收進入血液"], 3, ["腎臟也不是其最先出現位置。", "葡萄糖進血不是形成糞便。", "材料沒有呼吸道氣體交換。", "穿過小腸上皮進微血管就是吸收。"], ["最先出現於絨毛微血管，直接證明葡萄糖已跨越小腸壁。", "「由小腸吸收進入血液」符合位置與方向，其他路徑分屬排遺、呼吸或排泄。"]),
    question("BIO_R4_SQ_054_02", "BIO_R4_S054", "advanced", "脂質標記先在淋巴、後在血液，哪項解釋正確？", ["脂質初始進淋巴後可匯入血液", "脂質沒有跨過小腸壁", "淋巴把脂質送回小腸腔", "脂質會直接變成血液"], 0, ["先後紀錄符合淋巴匯入血液的路徑。", "進入絨毛淋巴已表示完成跨壁。", "正常方向是運離腸壁而非送回腸腔。", "血液不是由單一養分轉變而成。"], ["最先位置與十分鐘後位置構成淋巴到血液的連續運輸證據。", "「脂質初始進淋巴後可匯入血液」能解釋兩筆資料，其他選項否定觀察或顛倒方向。"]),
    question("BIO_R4_SQ_054_03", "BIO_R4_S054", "transfer", "若淋巴管阻塞但微血管正常，預測哪項最合理？", ["葡萄糖與脂質都完全不消化", "脂質標記進入血液的速度較可能下降", "葡萄糖一定改走氣管", "小腸立刻變成大腸"], 1, ["阻塞運輸管路不等於消化酵素失效。", "脂質初始淋巴路徑受阻會延緩後續入血。", "葡萄糖不會因阻塞進入呼吸道。", "器官不會因管路阻塞改變種類。"], ["資料顯示脂質先進淋巴，故淋巴阻塞最直接影響其後續匯入血液。", "「脂質標記進入血液的速度較可能下降」是由路徑作出的有限預測，沒有誇大為全部消化停止。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S055", "BIO_R4_S055",
  ["由器官正常功能推論消化異常的直接影響。", "限制因果範圍，區分消化、吸收與水分回收等不同障礙。"],
  [
    { id: "BIO_R4_L_S055_SEC_01", title: "由正常功能建立預測", content: "分析器官異常時，先說明該器官在正常情況下的主要作用，再推論失常後最直接下降的功能。這種推理比只背疾病名稱可靠，也能避免把局部異常誇大成所有系統停止。" },
    { id: "BIO_R4_L_S055_SEC_02", title: "消化液不足的影響", content: "唾液酵素不足可能使口腔澱粉初步分解減少；膽汁難以進入小腸則先影響脂質乳化；胰臟消化液不足可能影響多類養分在小腸的化學分解。" },
    { id: "BIO_R4_L_S055_SEC_03", title: "小腸異常影響吸收", content: "小腸絨毛受損會減少表面積與運輸管路，使消化後的小分子較難充分吸收。即使胃與酵素仍能分解食物，吸收效率也可獨立下降。" },
    { id: "BIO_R4_L_S055_SEC_04", title: "大腸與水分回收", content: "大腸主要吸收部分水分並形成糞便。內容物通過過快時，水分回收可能不足；停留過久時，水分被吸收較多，糞便可能較乾硬。這不等同大腸是主要養分消化場所。" },
  ],
  [
    { id: "BIO_R4_L_S055_EX_01", prompt: "膽管阻塞後脂質消化效率下降，最直接缺少哪項協助？", steps: ["辨認膽管運送膽汁到小腸。", "連結膽汁與脂質乳化功能。"], answer: "油滴乳化與接觸面積增加", why: "膽汁不足使大油滴較難分散，脂質酵素可接觸表面減少；直接影響是乳化協助，而不是所有酵素停止。" },
    { id: "BIO_R4_L_S055_EX_02", prompt: "絨毛變平但酵素正常，哪項功能最直接下降？", steps: ["確認化學消化仍可進行。", "由絨毛功能判斷吸收面積減少。"], answer: "小腸吸收", why: "絨毛提供大面積、薄上皮與管路，變平後即使小分子正常形成，穿過腸壁並被運走的量仍可能下降。" },
    { id: "BIO_R4_L_S055_EX_03", prompt: "大腸內容物移動過快且糞便含水多，最合理機制為何？", steps: ["辨認大腸的正常水分吸收角色。", "連結停留時間縮短與水分回收不足。"], answer: "水分來不及充分吸收", why: "內容物與大腸壁接觸時間縮短，部分水分尚未回收就排出，因此糞便含水較多；不是胃完全停止消化。" },
  ],
  [
    { belief: "一個消化器官異常會讓所有消化功能同時歸零。", whyWrong: "不同器官分工且可能互相補充，直接影響通常集中在原有功能。", correction: "先定位器官功能，再描述最直接障礙，不作全系統絕對化。" },
    { belief: "膽汁不足表示蛋白質酵素全部消失。", whyWrong: "膽汁主要協助脂質乳化，不是蛋白質酵素的唯一來源。", correction: "膽汁異常優先連結油滴分散與脂質消化效率。" },
    { belief: "小腸絨毛受損只會影響食物咀嚼。", whyWrong: "咀嚼發生在口腔，絨毛則直接參與小腸養分吸收。", correction: "依器官位置配對功能，絨毛受損應先考慮吸收面積下降。" },
    { belief: "大腸是蛋白質化學消化的主要場所。", whyWrong: "大腸主要與水分吸收及糞便形成相關，蛋白質消化重點較前。", correction: "大腸異常先分析水分與排遺，不把它當主要酵素消化器官。" },
  ],
  [
    { prompt: "膽汁不能進小腸，哪類消化較直接受影響？", answer: "脂質消化", reason: "膽汁乳化不足會減少脂質酵素與油滴的有效接觸面積。" },
    { prompt: "絨毛受損主要影響消化還是吸收？", answer: "吸收", reason: "絨毛提供吸收表面與管路，受損會降低小分子跨壁效率。" },
    { prompt: "大腸移動過快可能使糞便如何變化？", answer: "含水較多", reason: "內容物停留時間短，部分水分尚未被大腸充分吸收就排出。" },
  ],
));

questions.push(
  question("BIO_R4_Q_055_01", "BIO_R4_S055", "foundation", "膽汁難以進入小腸時，最直接受影響的是哪項作用？", ["脂質乳化", "牙齒咀嚼", "肺泡換氣", "腎臟製尿"], 0, ["膽汁的主要消化協助是乳化油滴。", "咀嚼由口腔牙齒完成。", "肺泡換氣不依賴膽汁。", "腎臟製尿也不是膽汁功能。"], ["膽汁經膽管進小腸並分散脂質，阻塞首先影響乳化。", "其餘功能分屬口腔、呼吸或泌尿系統，沒有直接連結。"]),
  question("BIO_R4_Q_055_02", "BIO_R4_S055", "foundation", "小腸絨毛受損最可能直接降低哪個功能？", ["吞嚥", "養分吸收", "咀嚼", "氣體交換"], 1, ["吞嚥主要發生在咽與食道。", "絨毛面積與管路受損會降低吸收。", "咀嚼發生在口腔牙齒。", "氣體交換主要在肺泡進行。"], ["由絨毛的大面積、薄上皮與運輸管路可推得直接功能為吸收。", "「養分吸收」符合受損位置，其餘作用位於不同器官系統。"]),
  question("BIO_R4_Q_055_03", "BIO_R4_S055", "foundation", "大腸內容物移動過快，最可能出現哪項結果？", ["脂質全部合成", "氧氣停止進血", "水分吸收不足", "牙齒數量減少"], 2, ["大腸移動速度不會使脂質全部合成。", "肺泡氣體交換不由大腸控制。", "停留短會使水分來不及充分回收。", "牙齒數量與大腸通過時間無關。"], ["大腸的主要相關功能是回收部分水分，時間縮短會降低回收。", "「水分吸收不足」能解釋含水較多的糞便，其他選項沒有器官功能連結。"]),
  question("BIO_R4_Q_055_04", "BIO_R4_S055", "standard", "若唾液分泌很少，哪項消化最先受到影響？", ["大腸吸收水分", "肺排二氧化碳", "腎臟排含氮廢物", "口腔中澱粉的初步分解"], 3, ["大腸水分吸收不靠唾液。", "二氧化碳由肺排出，與唾液無關。", "腎臟排泄也不由唾液控制。", "唾液中的澱粉酵素可開始分解澱粉。"], ["唾液直接作用位置在口腔，且含有能分解澱粉的酵素。", "「口腔中澱粉的初步分解」是最先、最直接影響，其他選項分屬不同系統。"]),
  question("BIO_R4_Q_055_05", "BIO_R4_S055", "standard", "小腸酵素正常但絨毛變平，最合理的結果是什麼？", ["小分子可形成但吸收量下降", "所有食物完全不能分解", "胃立即停止攪拌", "食道完全不能推送"], 0, ["消化保留而面積減少，吸收較受影響。", "酵素正常反駁完全不能分解。", "胃肌肉作用不由絨毛直接控制。", "食道運動也與小腸絨毛不同。"], ["題幹把化學消化與絨毛結構分開，應保留小分子形成。", "「小分子可形成但吸收量下降」精準描述吸收面積下降的後果，沒有擴張到其他器官。"]),
  question("BIO_R4_Q_055_06", "BIO_R4_S055", "standard", "胰臟消化液無法進入小腸，可能影響什麼？", ["只有牙齒外形", "小腸內多類養分的化學消化", "肺泡表面積", "大腦神經訊息"], 1, ["牙齒外形不由胰液維持。", "胰液含多種消化酵素，缺少會影響分解。", "肺泡表面積與消化液無關。", "神經訊息不是胰液直接作用目標。"], ["胰臟向小腸提供含多種酵素的消化液，可參與多類養分分解。", "「小腸內多類養分的化學消化」符合分泌方向與功能，其他選項屬無關構造。"]),
  question("BIO_R4_Q_055_07", "BIO_R4_S055", "standard", "大腸停留時間過久時，糞便可能較乾硬，主要原因是什麼？", ["澱粉變成氧氣", "膽汁全部消失", "更多水分被大腸吸收", "小腸絨毛數量增加"], 2, ["大腸不會把澱粉轉成氧氣。", "糞便乾硬不需假設膽汁消失。", "停留較久使水分回收較多。", "小腸絨毛不是大腸停留的直接變化。"], ["內容物與大腸壁接觸時間增加，水分可被回收得更多。", "「更多水分被大腸吸收」直接解釋糞便含水減少，其他選項缺乏因果關係。"]),
  question("BIO_R4_Q_055_08", "BIO_R4_S055", "advanced", "膽汁不足但脂質酵素量正常，脂質分解仍較慢，最合理原因為何？", ["酵素已變成紅血球", "脂質完全不存在", "胃無法運送食物", "油滴較大使酵素接觸面積較小"], 3, ["脂質酵素不會轉變成紅血球。", "題幹仍討論脂質受質。", "胃運送不是膽汁不足的直接結果。", "乳化不足會降低總接觸面。"], ["膽汁不足時大油滴不易分散，即使酵素正常，接觸機會仍降低。", "「油滴較大使酵素接觸面積較小」由乳化功能解釋速率，沒有誤認膽汁本身是酵素。"]),
  question("BIO_R4_Q_055_09", "BIO_R4_S055", "advanced", "若胃攪拌能力下降但小腸功能正常，最保守的推論為何？", ["胃內物理混合效率可能下降", "全身所有細胞立即死亡", "小腸絨毛必定完全消失", "肺泡不再交換氣體"], 0, ["胃肌肉作用下降會直接影響攪拌混合。", "局部消化異常不能推出全身立即死亡。", "胃功能下降不必然破壞絨毛。", "肺泡換氣也非直接後果。"], ["依正常功能推論，胃攪拌下降最直接影響物理混合。", "「胃內物理混合效率可能下降」限制在證據範圍，其他選項把局部異常過度擴張。"]),
  question("BIO_R4_Q_055_10", "BIO_R4_S055", "advanced", "某人消化產物正常卻血中養分偏低，優先檢查哪項功能？", ["牙齒顏色", "小腸吸收", "氣管送氣", "膀胱儲尿"], 1, ["牙齒顏色不能解釋吸收後血中濃度。", "消化正常而入血不足提示吸收障礙。", "氣管運送空氣不接收腸道養分。", "膀胱儲尿也不是養分入血關口。"], ["題幹已排除小分子形成問題，下一個關口是穿過小腸壁。", "「小腸吸收」沿消化吸收流程定位，其他器官與養分入血無直接關聯。"]),
  question("BIO_R4_Q_055_11", "BIO_R4_S055", "transfer", "藥物抑制大腸水分吸收，最可能觀察到哪種變化？", ["糞便水分減少", "唾液澱粉酵素增加", "糞便水分增加", "肺活量立刻加倍"], 2, ["吸收受抑制會保留更多水而非減少。", "大腸藥物不直接增加唾液酵素。", "較少水回收使更多水留在糞便。", "肺活量與大腸水分吸收無直接關係。"], ["抑制代表從大腸內容物移出的水減少，因此糞便含水增加。", "「糞便水分增加」符合物質流向，其他選項方向相反或跨到無關器官。"]),
  question("BIO_R4_Q_055_12", "BIO_R4_S055", "transfer", "比較兩病人：甲缺膽汁，乙絨毛受損，哪項區分最合理？", ["兩者都只影響咀嚼", "甲只影響呼吸，乙只影響排尿", "兩者作用完全相同", "甲先影響脂質乳化，乙先影響養分吸收"], 3, ["兩種異常都位於口腔咀嚼之後。", "膽汁與絨毛都不屬呼吸排尿器官。", "兩者分別涉及消化協助與吸收結構。", "此項依正常功能正確區分直接影響。"], ["膽汁分散油滴，絨毛提供吸收面與管路，功能層次不同。", "「甲先影響脂質乳化，乙先影響養分吸收」保留兩種異常的特異影響，避免把消化與吸收混為一談。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S055", "BIO_R4_S055", "organ-function-cases",
  { title: "三種消化異常觀察", text: "臨床教學模型呈現三種單一異常：甲的膽汁無法進入小腸；乙的小腸酵素正常但絨毛面積剩一半；丙的大腸內容物通過時間縮短。其餘器官功能設定正常。", note: "資料只供器官功能推理，不作個人疾病診斷。" },
  { summary: "表格列出三種單一器官異常與觀察結果。", colorIndependent: true, dataFallback: { columns: ["模型", "異常", "觀察"], rows: [["甲", "膽汁未進小腸", "大油滴較多"], ["乙", "絨毛面積減半", "血中吸收標記較少"], ["丙", "大腸通過加快", "糞便含水較多"]] } },
  [
    question("BIO_R4_SQ_055_01", "BIO_R4_S055", "standard", "甲模型出現較多大油滴，最直接缺少哪項作用？", ["小腸微血管運氧", "牙齒咀嚼", "膽汁乳化", "腎臟過濾"], 2, ["微血管主要運送養分而非乳化。", "牙齒不負責小腸內油滴乳化。", "膽汁未進小腸會使油滴較難分散。", "腎臟過濾不在消化道內完成。"], ["甲的唯一設定異常是膽汁缺席，大油滴保留符合乳化不足。", "「膽汁乳化」由異常與觀察直接配對，其他功能位於不同器官。"]),
    question("BIO_R4_SQ_055_02", "BIO_R4_S055", "advanced", "乙模型小分子形成正常但血中標記較少，最合理原因為何？", ["胃完全沒有食物", "肺泡將養分呼出", "唾液使養分全部排遺", "絨毛面積減少使吸收效率下降"], 3, ["題幹沒有設定胃缺少食物。", "肺泡主要交換呼吸氣體。", "唾液不會把全部養分變成糞便。", "吸收面積減半會降低進入血液的量。"], ["小分子正常排除消化障礙，血中較少則指向跨腸壁吸收下降。", "「絨毛面積減少使吸收效率下降」同時符合絨毛設定與觀察，是最直接的因果解釋。"]),
    question("BIO_R4_SQ_055_03", "BIO_R4_S055", "transfer", "丙模型若延長內容物在大腸停留時間，預測何者最合理？", ["糞便含水量可能下降", "氧氣吸收立刻加倍", "糞便一定完全消失", "膽汁變成蛋白質酵素"], 0, ["更多時間可讓大腸回收較多水分。", "大腸停留與肺泡吸氧無直接關係。", "延長停留不會使所有殘餘消失。", "時間改變不會改變膽汁物質種類。"], ["現有觀察把快速通過與高含水連結，反向操作可預測含水下降。", "「糞便含水量可能下降」是有限且可檢驗的推論，沒有跨越到無關系統。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S056", "BIO_R4_S056",
  ["運用均衡飲食概念分析生活餐點與個人需求。", "辨識多樣、適量與需求調整，避免單一食物或極端排除策略。"],
  [
    { id: "BIO_R4_L_S056_SEC_01", title: "均衡不是每樣等量", content: "均衡飲食是依身體需要攝取多類食物與養分，份量並非每一類完全相等。活動量、年齡與生長狀況不同，能量與材料需求會調整，但仍需兼顧多樣來源。" },
    { id: "BIO_R4_L_S056_SEC_02", title: "多樣來源降低缺漏", content: "不同食物的突出養分與其他成分不同，選擇多樣食物較能降低長期缺少某類養分的風險。均衡不能只靠一種補充品，也不能因某食物富含一種養分就視為完整餐。" },
    { id: "BIO_R4_L_S056_SEC_03", title: "適量同樣重要", content: "人體需要醣類、蛋白質、脂質、維生素、礦物質與水，但需要不等於越多越好。長期過量或不足都可能造成問題，應依需求、份量與食物組合共同判斷。" },
    { id: "BIO_R4_L_S056_SEC_04", title: "從餐盤找不足與過度", content: "分析生活餐點時先列主要食物類別，再看是否只有精製澱粉、缺少蔬果或蛋白質來源，或油糖過量。改善方案應補足缺少類別並調整份量，而非把整餐全部替換成單一食品。" },
  ],
  [
    { id: "BIO_R4_L_S056_EX_01", prompt: "早餐只有含糖飲料，如何作最基本改善？", steps: ["辨識原餐點來源單一且糖分突出。", "加入不同食物類別與較完整組合。"], answer: "加入全穀或根莖、蛋白質來源與水果等", why: "原餐點缺少多樣養分與飽足來源，增加不同類別能改善均衡；不是再加另一杯含糖飲料或只補單一維生素。" },
    { id: "BIO_R4_L_S056_EX_02", prompt: "運動量增加的學生是否只需吃更多油脂？", steps: ["確認活動量增加可能提高能量需求。", "檢查是否仍需材料、調節物質與水。"], answer: "不是，應依需求調整整體均衡餐點", why: "活動增加不代表能量只能來自油脂，仍需醣類、蛋白質、水與其他養分；調整應兼顧種類與份量。" },
    { id: "BIO_R4_L_S056_EX_03", prompt: "某食品富含蛋白質，能否長期取代所有餐點？", steps: ["區分富含一種養分與包含全部需求。", "檢查長期單一來源可能造成的缺漏。"], answer: "不能", why: "富含蛋白質不表示具有適量醣類、脂質、維生素、礦物質與水，長期單一食物難以符合多樣和適量原則。" },
  ],
  [
    { belief: "均衡表示六大養分每天吃完全相同重量。", whyWrong: "不同養分需求量與食物來源不同，均衡不是機械式等重分配。", correction: "依個人需求安排多樣食物與適當份量，不要求每類等量。" },
    { belief: "某食物很健康就可以無限量攝取。", whyWrong: "任何食物都有特定成分與份量，過量可能排擠其他食物或造成負擔。", correction: "健康選擇仍需適量，並與其他食物類別共同組成餐點。" },
    { belief: "要控制體重就應完全不吃脂質。", whyWrong: "脂質仍有儲能、保溫、保護與其他生理角色，重點是適量與來源。", correction: "調整總份量與食物組合，不把必要養分類別完全排除。" },
    { belief: "只吃維生素補充品就能取代正餐。", whyWrong: "維生素不能提供完整能量、蛋白質材料與所有食物成分。", correction: "補充品不能替代多樣食物，正餐仍需兼顧供能、構造與調節需求。" },
  ],
  [
    { prompt: "均衡飲食是否要求每類食物完全等量？", answer: "不是", reason: "各類需求與功能不同，應依個人狀況安排多樣且適當份量。" },
    { prompt: "單一高蛋白食品能否取代所有餐點？", answer: "不能", reason: "單一食品難以同時提供各類養分與符合長期適量原則。" },
    { prompt: "分析餐點除了種類還要看什麼？", answer: "份量與個人需求", reason: "同一組合在活動量與份量不同時，適合程度也可能不同。" },
  ],
));

questions.push(
  question("BIO_R4_Q_056_01", "BIO_R4_S056", "foundation", "下列哪一項最符合均衡飲食的基本概念？", ["攝取多樣食物並注意適量", "每餐只吃一種最喜歡的食物", "完全排除所有脂質", "只靠補充品取代正餐"], 0, ["多樣與適量能兼顧不同養分需求。", "單一食物容易造成養分來源缺漏。", "脂質具有必要功能，不應完全排除。", "補充品不能提供完整餐點所需成分。"], ["均衡的核心不是單一食物，而是多樣來源、適當份量與需求配合。", "「攝取多樣食物並注意適量」包含這些原則，其他選項皆採極端或單一替代策略。"]),
  question("BIO_R4_Q_056_02", "BIO_R4_S056", "foundation", "早餐只有含糖飲料，最合理的改善方向為何？", ["再加一杯含糖飲料", "加入穀類、蛋白質來源與水果等", "完全不吃早餐", "只加入維生素錠"], 1, ["只增加同類糖分會讓來源仍然單一。", "增加不同類別可補足能量、材料與調節需求。", "不吃早餐沒有改善原本食物組合。", "維生素錠不能取代完整食物與能量來源。"], ["原早餐問題是來源單一與糖分突出，改善應增加多樣食物。", "「加入穀類、蛋白質來源與水果等」提供多類來源，其餘方案仍單一、跳餐或以補充品取代。"]),
  question("BIO_R4_Q_056_03", "BIO_R4_S056", "foundation", "關於適量的敘述，下列何者正確？", ["需要的養分越多越好", "健康食物可以無限吃", "養分攝取需依需求避免長期過量或不足", "所有人的份量必須完全一樣"], 2, ["生理需要不代表攝取可無限增加。", "健康食物仍有份量與整體搭配問題。", "此項正確表達適量與個別需求。", "活動量與年齡不同，份量可合理調整。"], ["適量同時避免不足與過量，且需考慮個人活動與生長狀況。", "「養分攝取需依需求避免長期過量或不足」保留彈性與界線，其他項目都使用無限或完全相同。"]),
  question("BIO_R4_Q_056_04", "BIO_R4_S056", "standard", "某食品富含蛋白質，為何仍不能長期取代所有餐點？", ["蛋白質完全沒有作用", "所有食物都不含水", "人體只需要醣類", "單一食品難以提供適量的全部養分"], 3, ["蛋白質是生長修補的重要材料。", "多種食物都含不同程度的水。", "人體還需要其他多類養分。", "富含一類不等於滿足完整需求。"], ["題幹的富含只說蛋白質突出，沒有證明其他需求都能滿足。", "「單一食品難以提供適量的全部養分」正確運用多樣與完整性，其他項目則否定基本營養事實。"]),
  question("BIO_R4_Q_056_05", "BIO_R4_S056", "standard", "活動量增加時，最合理的飲食調整原則為何？", ["依能量與修補需求調整整體份量和組合", "只無限增加脂質", "只喝水而不吃食物", "完全取消蛋白質來源"], 0, ["活動需求提高仍需多類養分共同配合。", "只增加脂質會忽略其他養分與適量。", "水不能提供全部能量與構造材料。", "訓練後組織修補仍需要蛋白質。"], ["需求變化可以調整份量，但均衡與多樣原則仍然保留。", "「依能量與修補需求調整整體份量和組合」同時處理能量、修補與整體組合，避免單一極端。"]),
  question("BIO_R4_Q_056_06", "BIO_R4_S056", "standard", "某餐只有白飯與甜點，最值得優先改善的問題是什麼？", ["食物種類太多", "來源偏單一且缺少其他類別", "蛋白質一定過量", "水分一定無限多"], 1, ["兩種食物不代表種類過多。", "餐點偏向澱粉與糖，其他來源不足。", "題幹沒有高蛋白食物可支持過量。", "也沒有飲水量資料可作此結論。"], ["先由實際餐點辨識突出與缺少類別，白飯甜點組合來源偏單一。", "「來源偏單一且缺少其他類別」是資料可支持的問題，不能臆測蛋白質或水分數量。"]),
  question("BIO_R4_Q_056_07", "BIO_R4_S056", "standard", "控制體重時完全不攝取脂質，何處不合理？", ["脂質只存在飲水中", "脂質不能被消化", "脂質仍有必要功能，應調整種類與份量", "脂質就是所有維生素"], 2, ["脂質存在於多種食物而非只在水中。", "人體具有脂質消化相關作用。", "必要不等於無限，適量調整較合理。", "脂質與維生素是不同養分類別。"], ["脂質具有儲能、保溫與保護等角色，不能因控制體重就完全排除。", "「脂質仍有必要功能，應調整種類與份量」同時承認功能與份量調整，符合均衡原則。"]),
  question("BIO_R4_Q_056_08", "BIO_R4_S056", "advanced", "兩名同齡學生活動量差很多，飲食分析時最合理的做法是什麼？", ["兩人所有份量必須完全相同", "活動多者只能吃脂質", "活動少者完全不需蛋白質", "保留多樣原則並依需求調整份量"], 3, ["活動量差異可能造成能量需求不同。", "能量來源不應只限一種養分。", "活動少仍需要組織維持與修補材料。", "此項兼顧共同原則與個別差異。"], ["均衡飲食不是固定菜單，份量可依活動需求合理調整。", "「保留多樣原則並依需求調整份量」保留多樣性，又沒有用單一養分或完全排除處理差異。"]),
  question("BIO_R4_Q_056_09", "BIO_R4_S056", "advanced", "一週餐點每天都只吃同一種完整食品，最大風險為何？", ["長期可能缺少該食品不突出的養分", "食物一定完全沒有熱量", "所有養分會變成水", "消化道順序會倒轉"], 0, ["單一來源難以長期涵蓋不同養分需求。", "完整食品仍可能提供一定熱量。", "養分類別不會因重複攝取變成水。", "餐點種類也不會改變器官排列。"], ["即使一種食品成分不少，長期單一仍可能有比例與種類缺漏。", "「長期可能缺少該食品不突出的養分」是合理營養風險，其他選項沒有生物學因果依據。"]),
  question("BIO_R4_Q_056_10", "BIO_R4_S056", "advanced", "判斷一份餐點是否均衡，哪種資料最有用？", ["餐盤顏色是否漂亮", "食物種類、份量與食用者需求", "餐具價格是否昂貴", "食物名稱字數是否相同"], 1, ["顏色可提示種類但不能單獨判定養分。", "三類資料共同支持組合與適量分析。", "餐具價格不代表食物營養價值。", "名稱字數也與養分內容無關。"], ["均衡需同時看吃了什麼、吃多少與誰要吃。", "「食物種類、份量與食用者需求」提供必要資訊，其他選項只涉及外觀、價格或文字形式。"]),
  question("BIO_R4_Q_056_11", "BIO_R4_S056", "transfer", "校外教學午餐含飯、豆腐、蔬菜與水果，最合理評估為何？", ["一定適合每個人的任何份量", "因有飯所以完全不均衡", "種類較多，但仍需看份量與個人需求", "豆腐可取代全部飲水"], 2, ["種類完整不代表任何份量都適合。", "飯可作為醣類來源，不能因此判不均衡。", "此項保留多樣優勢與適量判斷。", "豆腐不能取代人體所需水分。"], ["餐點包含多類食物是正向證據，但均衡仍需份量與需求資訊。", "「種類較多，但仍需看份量與個人需求」是證據範圍內的評估，不使用一定或完全等絕對說法。"]),
  question("BIO_R4_Q_056_12", "BIO_R4_S056", "transfer", "廣告宣稱一顆錠劑可取代所有正餐，最科學的質疑是什麼？", ["錠劑一定沒有任何物質", "正餐只需要維生素", "人體不需要能量", "是否能提供適量能量、蛋白質及其他各類養分"], 3, ["錠劑仍由某些物質組成，不能說完全沒有。", "正餐需求遠超過維生素一類。", "人體活動與生命作用都需要能量。", "完整需求是檢驗取代宣稱的關鍵。"], ["取代所有正餐是全面宣稱，必須證明能滿足多類養分與適量需求。", "「是否能提供適量能量、蛋白質及其他各類養分」提出可檢驗的營養問題，其他選項本身就是錯誤前提。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S056", "BIO_R4_S056", "meal-planning",
  { title: "三份午餐紀錄", text: "學生比較三份午餐。甲餐只有白飯與含糖飲料；乙餐有飯、煎蛋、青菜與水；丙餐只有大量雞胸肉。表格只描述主要食物組合，實際是否適合仍需配合份量與食用者需求。", note: "多樣性較高不代表份量必然適合所有人。" },
  { summary: "表格列出三份午餐的食物組合與來源多樣性。", colorIndependent: true, dataFallback: { columns: ["餐點", "主要內容", "來源多樣性"], rows: [["甲", "白飯、含糖飲料", "低"], ["乙", "飯、蛋、青菜、水", "較高"], ["丙", "大量雞胸肉", "低"]] } },
  [
    question("BIO_R4_SQ_056_01", "BIO_R4_S056", "standard", "只看食物種類，哪份餐點的來源多樣性相對較高？", ["甲餐", "乙餐", "丙餐", "三餐完全相同"], 1, ["甲餐主要集中在白飯與含糖飲料。", "乙餐包含主食、蛋、蔬菜與水等多種來源。", "丙餐只有大量單一雞胸肉。", "三餐的食物組合明顯不同。"], ["依表中主要內容計數與分類，乙餐的食物來源最為多樣。", "題目只比較多樣性，尚未宣稱乙餐份量一定適合每個人。"]),
    question("BIO_R4_SQ_056_02", "BIO_R4_S056", "advanced", "為何不能只因乙餐種類較多就斷定適合所有學生？", ["乙餐沒有任何養分", "種類越多一定越有害", "仍需考慮份量、活動量與個人需求", "水會破壞所有食物"], 2, ["乙餐含多種食物，並非沒有養分。", "多樣通常有助降低缺漏，並非必然有害。", "均衡還包含適量與需求差異。", "水是人體所需物質，不會破壞所有食物。"], ["材料明示是否適合還需配合份量與食用者需求。", "「仍需考慮份量、活動量與個人需求」完整保留這個限制，避免把來源多樣直接等同普遍適量。"]),
    question("BIO_R4_SQ_056_03", "BIO_R4_S056", "transfer", "若要改善丙餐，哪個方案最符合均衡原則？", ["再加更多雞胸肉", "完全不喝水", "把所有食物換成維生素錠", "保留適量蛋白質並加入主食、蔬果與水"], 3, ["只增加同一食物仍缺乏多樣來源。", "水是人體運輸與調節所需物質。", "補充品無法取代完整食物與能量來源。", "此方案增加不同類別並控制蛋白質份量。"], ["丙餐問題是單一且大量，改善應保留適量並補足其他類別。", "「保留適量蛋白質並加入主食、蔬果與水」同時處理多樣與適量，其他方案延續或加重原問題。"]),
  ],
));

questions.find((item) => item.id === "BIO_R4_Q_049_08").reasons[0] = "食團離開胃時會先通過與小腸相接的胃出口。";
questions.find((item) => item.id === "BIO_R4_Q_049_12").reasons[1] = "胃到咽再到口腔是朝消化道入口反向移動。";
questions.find((item) => item.id === "BIO_R4_Q_050_02").reasons[2] = "排遺是由肛門排出未被消化吸收的食物殘餘。";
questions.find((item) => item.id === "BIO_R4_Q_050_04").reasons[0] = "食物位置改變只表示運送，沒有證明分子轉變。";
questions.find((item) => item.id === "BIO_R4_Q_050_11").reasons[0] = "研磨只改變顆粒大小，不會因此製造消化酵素。";
questions.find((item) => item.id === "BIO_R4_Q_051_08").reasons[0] = "澱粉是可被消化利用的醣類養分，不是非養分物質。";
